class ScriptLiftFailed(RuntimeError):
    """Phase A10: raised when `_lift_indented_exports` detects a nested export
    it cannot safely lift (unbalanced braces, outer-scope refs). The caller
    treats this as a corrective signal and triggers the retry-with-hint loop
    rather than letting the silent return-unchanged sneak the bad script past.
    """


def _stringify(value: object) -> str:
    """R18b helper — render a JSON value as a Postman query/header string.

    Postman query and header values are strings; the LLM can put bools,
    ints, lists, etc. in the body. JSON-encode complex types so the
    SUT receives the same shape it would have in the body, and
    primitives stringify naturally (no surrounding quotes).
    """
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if value is None:
        return ""
    if isinstance(value, (int, float)):
        return str(value)
    return json.dumps(value)


def _lift_indented_exports(content: str) -> str:
    """Lift `export function NAME(...) { ... }` blocks from inside any
    enclosing block to module top level (just before `export default function`).

    The LLM has a strong systematic bias (Mocha/Jest training residue) toward
    nesting `export function setup()` inside `export default function ()`.
    k6's goja parser rejects this with "export only allowed in global scope"
    and the script never runs. Verified across 4 runs (4b700c, 786453,
    d2750de5): 7 of 12 k6 generations show this exact defect — even with
    corrective retry hints, the LLM keeps producing the broken shape.

    The transform finds each indented `export function NAME(...)`, walks
    forward with a brace counter to find the matching closing `}`, then
    cuts the block out of its enclosing position and splices it back at
    module top level.

    Phase A10: raises `ScriptLiftFailed` when an indented export is detected
    but cannot be safely lifted (unbalanced braces or outer-scope refs).
    Previously the function silently returned unchanged content and relied on
    a downstream regex to catch the failure — that path worked but obscured
    debugging. Raising here surfaces the exact reason in the corrective hint.

    Returns the (possibly transformed) content. Idempotent: safe to call
    repeatedly. Never modifies content that has only top-level exports.
    """
    # Identify block: indented `export function NAME(args) {`
    pattern = re.compile(
        r"^(?P<indent>[ \t]+)export\s+function\s+(?P<name>\w+)\s*\([^)]*\)\s*\{",
        re.MULTILINE,
    )
    while True:
        m = pattern.search(content)
        if not m:
            return content
        # Find matching closing brace via balanced counter
        block_start = m.start()
        body_start = m.end() - 1  # the `{` itself
        depth = 0
        i = body_start
        while i < len(content):
            ch = content[i]
            if ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    block_end = i + 1
                    break
            i += 1
        else:
            # Phase A10: surface the failure reason instead of silent return.
            line_no = content[:body_start].count("\n") + 1
            raise ScriptLiftFailed(
                f"k6 indented export at line {line_no} has unbalanced braces; "
                f"the lifter cannot find its matching closing `}}`. Regenerate "
                f"with the export at module top level."
            )
        block_text = content[block_start:block_end]
        # Heuristic: do any tokens in the block body look like outer-scope
        # references? We check for bare identifiers that AREN'T declared
        # inside the block (no `const|let|var|function NAME` before use).
        body_only = content[body_start + 1:block_end - 1]
        # Identifiers declared inside the block:
        local_decls = set(re.findall(
            r"\b(?:const|let|var|function)\s+(\w+)",
            body_only,
        ))
        # Identifiers actually USED (not just appearing in object keys / strings):
        # We only flag patterns where an identifier is followed by `.method` or
        # `(args)` — i.e. a property access or function call. This excludes
        # object literal keys (`{ token: 'x' }`) which look like identifiers
        # but aren't variable references. Strip strings/comments first.
        stripped_body = re.sub(r"'[^'\n]*'|\"[^\"\n]*\"|`[^`]*`|//[^\n]*|/\*.*?\*/",
                               "", body_only, flags=re.DOTALL)
        # Match `IDENTIFIER.x` or `IDENTIFIER(...)` — actual usage patterns
        used_as_var = set(re.findall(
            r"\b([a-z_][\w]*)\s*[.(]",
            stripped_body,
        ))
        # Builtins / JS keywords / k6 globals — definitely not outer-scope refs:
        _BUILTINS = {
            "http", "check", "sleep", "console", "JSON", "Math", "Date",
            "URL", "Error", "Promise", "Array", "Object", "String", "Number",
            "Boolean", "true", "false", "null", "undefined", "this", "return",
            "if", "else", "for", "while", "switch", "case", "break", "continue",
            "throw", "try", "catch", "finally", "new", "typeof", "instanceof",
            "in", "of", "let", "const", "var", "function", "async", "await",
            "import", "from", "export", "default", "as", "yield", "void",
            "delete", "do", "with", "class", "extends", "super", "static",
            "get", "set", "fetch", "open", "send", "log", "warn", "info",
            "error", "debug", "trace", "parse", "stringify", "now", "random",
        }
        _ENV_REFS = {"BASE_URL", "AUTH_TOKEN", "API_BASE_URL", "__ENV"}
        outer_refs = used_as_var - local_decls - _BUILTINS - _ENV_REFS
        # Drop short single-letter idents (loop counters, lambda params)
        outer_refs = {r for r in outer_refs if len(r) > 2 and not r.isupper()}
        if outer_refs:
            # Phase A10: raise immediately so the corrective hint cites the
            # actual identifiers; the previous return-unchanged + downstream
            # regex path lost the outer_refs detail in the error message.
            line_no = content[:block_start].count("\n") + 1
            raise ScriptLiftFailed(
                f"k6 indented export `{m.group('name')}` at line {line_no} "
                f"references outer-scope identifiers {sorted(outer_refs)!r}; "
                f"lifting would break semantics. Regenerate with the export "
                f"at module top level and pass these as parameters."
            )
        # Lift: cut out the block (and its leading whitespace + trailing newline)
        # and splice before the first `export default function`.
        # Trim leading whitespace on the block's line, plus any trailing
        # blank line so we don't leave an empty hole.
        line_start = content.rfind("\n", 0, block_start) + 1
        # Include up to and including the next newline after block_end
        chunk_end = block_end
        if chunk_end < len(content) and content[chunk_end] == "\n":
            chunk_end += 1
        # Re-indent the lifted block to column 0
        lifted = "\n".join(
            line[len(m.group("indent")):] if line.startswith(m.group("indent")) else line
            for line in content[line_start:chunk_end].splitlines()
        )
        if not lifted.endswith("\n"):
            lifted += "\n"
        # Remove the block from its original position
        content_minus = content[:line_start] + content[chunk_end:]
        # Find insertion point: just before `^export default function` (or at
        # end of file if no default export found yet)
        insert_at = re.search(r"^export\s+default\s+function", content_minus, re.MULTILINE)
        if insert_at:
            content = content_minus[:insert_at.start()] + lifted + "\n" + content_minus[insert_at.start():]
        else:
            # No default function — append at end (rare, but valid for
            # scripts that use per-scenario `exec:` instead of default)
            content = content_minus.rstrip() + "\n\n" + lifted
        # Loop continues to find the next indented export, if any.


# R186 — :param name → session-id key (only ids we actually hold). Shared by the
# R180 prompt block AND the discovery-probe route feed so both resolve identically.
_R186_PARAM_TO_SESSION_ID = {
    "orgid": "organization_id", "org_id": "organization_id", "organizationid": "organization_id",
    "space_id": "workspace_id", "spaceid": "workspace_id", "space": "workspace_id",
    "workspaceid": "workspace_id", "workspace_id": "workspace_id",
    "project_id": "project_id", "projectid": "project_id",
    "subscriber_id": "subscriber_id", "subscription_id": "subscription_id",
    "account_id": "account_id",
}


async def _r212_resolve_app_flow_ids(ids: dict, env_name: str | None,
                                     *, api_base_url: str | None = None) -> dict:
    """R212 layer-2 — read the LIVE cm hierarchy for VALID workspace_id +
    project_id (and their org), to resolve the deep app-flow routes
    (/workspace/{space_id}/project/{project_id}/...).

    WHY: harvest_session_ids_from_storage returns STALE workspace/project ids
    (the JWT carries only org/account/subscriber; harvest's workspace/project
    values are not in the live cm data) → the deep routes resolved to wrong ids
    → the data XHR 401s → the SPA LOGS OUT. This GETs the workspaces
    cm list and returns the first workspace that HAS a project, using the
    workspace's OWN organization (multi-org-aware: the account's workspaces can
    live under a different org than the JWT's). Returns {} on any failure (caller
    keeps harvest's values). Killswitch ARTA_R212_APP_FLOW_IDS_DISABLE=1."""
    import os
    if os.environ.get("ARTA_R212_APP_FLOW_IDS_DISABLE") == "1":
        return {}
    account = ids.get("root_account_id") or ids.get("account_id")
    if not account:
        return {}
    session_tok = ids.get("session_token") or ids.get("session_token")
    if not session_tok:
        try:
            from .auth_refresher import _find_storage_state_path, _read_storage_state
            _sp = _find_storage_state_path(env_name)
            _ss = _read_storage_state(_sp) if _sp else None
            for _c in (_ss or {}).get("cookies", []):
                if str(_c.get("name", "")).lower() == "session-token":
                    session_tok = _c.get("value")
                    break
        except Exception:
            session_tok = None
    base = (api_base_url or os.environ.get("API_BASE_URL")
            or os.environ.get("TARGET_API_BASE_URL") or "").rstrip("/")
    if not session_tok or not base:
        return {}
    path = (f"/{account}/api/collection/{account}/user/private/cm/v1/"
            f"composite_default/composite_svc_workspaces")
    import httpx
    try:
        async with httpx.AsyncClient(timeout=15) as _client:
            _r = await _client.get(base + path, headers={"Authorization": f"Bearer {session_tok}"})
            if _r.status_code != 200:
                log.info("R212 app-flow ids: workspaces cm list → %d (no override)", _r.status_code)
                return {}
            data = _r.json()
    except Exception as _exc:
        log.debug("R212 app-flow ids: cm read failed: %s", _exc)
        return {}
    for _k, _v in (data.items() if isinstance(data, dict) else []):
        if _k in ("Collection", "last_evaluated_key") or not isinstance(_v, list):
            continue
        for _item in _v:
            _pl = _item.get("payload", {}) if isinstance(_item, dict) else {}
            _projects = _pl.get("composite_svc_projects") or []
            _ws = _pl.get("__auto_id__")
            if _ws and _projects:
                out = {"workspace_id": _ws, "project_id": _projects[0]}
                _org = _pl.get("organization_id")
                if isinstance(_org, list) and _org:
                    out["organization_id"] = _org[0]
                elif isinstance(_org, str) and _org:
                    out["organization_id"] = _org
                log.info("R212 app-flow ids: LIVE cm hierarchy → workspace=%s project=%s "
                         "org=%s (overriding stale harvest values)",
                         _ws[:8], str(_projects[0])[:8], str(out.get("organization_id", ""))[:8])
                return out
    return {}


def _r215_norm_id(v):
    """R215 — a cm org/workspace linkage field may be a str id, a [id] list,
    a [{...}] item list, or a {id} dict. Normalize to the bare id string."""
    if isinstance(v, list):
        v = v[0] if v else None
    if isinstance(v, dict):
        return v.get("id") or v.get("__auto_id__")
    return v


def _r215_build_app_state(orgs: list, workspaces: list, projects: list) -> dict:
    """R215 Item-0 (pure, unit-testable) — build the SPA app-state localStorage
    keys from live cm item lists. Picks a CONSISTENT (org, workspace, project)
    triple (a project whose `payload.organization_id` + `payload.workspace`
    both resolve), so the SPA leaves the org/project SELECTION wall and renders
    data views. Returns `{selectedOrganization, selectedWorkspace, selectedProject}`
    where each value is the JSON-stringified FULL cm item (the SPA reads
    `selectedProject.payload.id` and sibling fields — minimal stubs are NOT
    enough). Empty dict when no consistent triple is derivable.

    Keys are camelCase (confirmed from captured SPA traffic: `selectedProject`
    354k hits, `selectedOrganization` 219k, `selectedWorkspace` 98k)."""
    if not (orgs and projects):
        return {}
    org_by_id = {(_o.get("payload") or {}).get("id"): _o for _o in orgs if isinstance(_o, dict)}
    ws_by_id = {(_w.get("payload") or {}).get("id"): _w for _w in workspaces if isinstance(_w, dict)}
    chosen = None
    for _p in projects:
        if not isinstance(_p, dict):
            continue
        _pl = _p.get("payload") or {}
        _oid, _wid = _r215_norm_id(_pl.get("organization_id")), _r215_norm_id(_pl.get("workspace"))
        if _oid in org_by_id and _wid in ws_by_id:
            chosen = (org_by_id[_oid], ws_by_id[_wid], _p)
            break
    if not chosen:  # fallback: first project + best-effort org/ws
        _p = projects[0]
        _pl = _p.get("payload") or {}
        _org = org_by_id.get(_r215_norm_id(_pl.get("organization_id"))) or orgs[0]
        _ws = ws_by_id.get(_r215_norm_id(_pl.get("workspace"))) or (workspaces[0] if workspaces else None)
        if not _ws:
            return {}
        chosen = (_org, _ws, _p)
    _org, _ws, _proj = chosen
    return {
        "selectedOrganization": json.dumps(_org),
        "selectedWorkspace": json.dumps(_ws),
        "selectedProject": json.dumps(_proj),
    }


async def _r215_resolve_app_state(ids: dict, env_name: str | None,
                                  *, api_base_url: str | None = None) -> dict:
    """R215 Item-0 — resolve the SPA app-state localStorage (selected org/
    workspace/project, full cm items) from the LIVE cm hierarchy so a
    fresh-cookie SPA renders DATA VIEWS instead of the org/project selection
    wall. Without this, axe / PW-UI / the discovery probe scan the selection
    UI, not the real app → no real signal. Returns {} on any failure (caller
    keeps current behavior). Killswitch ARTA_R215_APP_STATE_DISABLE=1.
    Mirrors `_r212_resolve_app_flow_ids`'s cm-read + the verified session
    one-off; reuses the full-cm-item shape the SPA actually reads."""
    import os
    if os.environ.get("ARTA_R215_APP_STATE_DISABLE") == "1":
        return {}
    account = ids.get("root_account_id") or ids.get("account_id")
    session_tok = ids.get("session_token") or ids.get("session_token")
    if not session_tok:
        try:
            from .auth_refresher import _find_storage_state_path, _read_storage_state
            _sp = _find_storage_state_path(env_name)
            _ss = _read_storage_state(_sp) if _sp else None
            for _c in (_ss or {}).get("cookies", []):
                if str(_c.get("name", "")).lower() == "session-token":
                    session_tok = _c.get("value")
                    break
        except Exception:
            session_tok = None
    base = (api_base_url or os.environ.get("API_BASE_URL")
            or os.environ.get("TARGET_API_BASE_URL") or "").rstrip("/")
    if not account or not session_tok or not base:
        return {}
    _qp = "filters=null&last_evaluated_key=null&page_size=1000&include_detail=false"

    async def _cm(_type: str) -> list:
        path = (f"/{account}/api/collection/{account}/user/private/cm/v1/"
                f"composite_default/{_type}?{_qp}")
        import httpx
        try:
            async with httpx.AsyncClient(timeout=15) as _client:
                _r = await _client.get(base + path, headers={"Authorization": f"Bearer {session_tok}"})
                if _r.status_code != 200:
                    return []
                _data = _r.json()
        except Exception:
            return []
        _arrs = [v for k, v in (_data.items() if isinstance(_data, dict) else [])
                 if isinstance(v, list) and v and isinstance(v[0], dict)]
        return _arrs[0] if _arrs else []

    orgs = await _cm("organizationss")
    workspaces = await _cm("composite_svc_workspaces")
    projects = await _cm("composite_svc_projects")
    app_state = _r215_build_app_state(orgs, workspaces, projects)
    if app_state:
        log.info("R215 Item-0: resolved live SPA app-state (org+workspace+project) "
                 "from cm — SPA will render data views, not the selection wall")
    return app_state


async def resolve_frontend_routes_for_project(project: dict, env_name: str | None = None) -> list[dict]:
    """R186 KEYSTONE — resolve the SUT's real React-Router routes with :params
    substituted from the authenticated session.

    Single source of truth reused by (a) the R180 PW-prompt navigation constraint
    and (b) the discovery-probe route feed (discovery_executor) — so the probe walks
    the SAME real routes the LLM is told to use, instead of guessing API paths.

    Returns a list of dicts:
        {route, resolved_route, fully_resolved, unresolved_params,
         test_ids, buttons, form_fields, relevance_terms}
    `fully_resolved` routes (no leftover :param) are the ones safe to navigate; the
    probe MUST only navigate those (partial routes 404→/login). Best-effort: returns
    [] on any failure (missing GitHub token, no storage state, etc.).
    """
    try:
        from .github_context import extract_frontend_routes
        from .auth_refresher import _find_storage_state_path, _read_storage_state
        from .auth_chain import harvest_session_ids_from_storage
    except Exception:
        return []
    if not isinstance(project, dict) or not project:
        return []
    try:
        fe_routes = await extract_frontend_routes(project) or []
    except Exception:
        fe_routes = []
    if not fe_routes:
        return []
    try:
        _sp = _find_storage_state_path(env_name)
        _ss = _read_storage_state(_sp) if _sp else None
        ids = harvest_session_ids_from_storage(_ss) if _ss else {}
    except Exception:
        ids = {}
    # R212 layer-2 — override STALE harvest workspace/project ids with the LIVE
    # cm-hierarchy values so the deep app-flow routes (/workspace/{space_id}/
    # project/{project_id}/...) resolve to ids that don't 401→logout.
    try:
        _api_base = ((project.get("environments") or {}).get(env_name or "staging") or {}).get("api_base_url")
        _live_ids = await _r212_resolve_app_flow_ids(ids, env_name, api_base_url=_api_base)
        if _live_ids:
            ids = {**ids, **_live_ids}
    except Exception:
        pass

    def _resolve(route: str):
        unresolved: list[str] = []

        def _sub(m):
            p = m.group(1)
            key = _R186_PARAM_TO_SESSION_ID.get(p.lower())
            val = ids.get(key) if key else None
            if val:
                return "/" + str(val)
            unresolved.append(p)
            return "/:" + p
        return re.sub(r"/:([A-Za-z_][A-Za-z0-9_]*)", _sub, route), unresolved

    out: list[dict] = []
    seen: set = set()
    for r in fe_routes:
        rt = (r.get("route") or "").rstrip("/*")
        if not rt or rt in seen:
            continue
        seen.add(rt)
        resolved, unresolved = _resolve(rt)
        out.append({
            "route": rt,
            "resolved_route": resolved,
            "fully_resolved": not unresolved,
            "unresolved_params": unresolved,
            "test_ids": r.get("test_ids") or [],
            "buttons": r.get("buttons") or [],
            "form_fields": r.get("form_fields") or [],
        })
    return out


class AutomationEngineerAgent:
    """
    TEA Automation Engineer Agent.

    Reads Gherkin scenarios + risk profiles → generates ready-to-run
    automation scripts for the correct tool chain per scenario type.

    Tool selection:
      UI scenarios          → Playwright (TypeScript, POM)
      API scenarios         → Newman Postman Collection (JSON)
      Performance scenarios → k6 (JavaScript)
      Security scenarios    → OWASP ZAP config (YAML)
      Legacy/explicit       → Selenium (Python pytest) or Cypress
    """

    def __init__(
        self,
        client: AsyncAnthropic,
        model: str = "claude-haiku-4-5-20251001",
        multi_tool_model: str = "claude-sonnet-4-6",
        base_config: object | None = None,
        tool_client_cache: dict | None = None,
    ):
        self._client = client
        self._model = model
        # R217 — multi-tool batch model env-configurable. Default sonnet (the
        # historical "better marker adherence" tier) is PRESERVED, but live
        # bulk-gen evidence on the serialized claude_code CLI showed sonnet at
        # ~9 min/call AND producing only 1/5 tool markers (the haiku sequential
        # fallback was 28s AND produced the tool) → ~7hr/21-req run. Set
        # ARTA_MULTI_TOOL_MODEL=claude-haiku-4-5-20251001 for the CLI bulk path
        # to cut the per-req Stage-3 from ~18min → ~2.5min. R127.C escalation
        # can still bump quality-critical retries to a stronger tier.
        import os as _os_r217mt
        self._multi_tool_model = _os_r217mt.environ.get("ARTA_MULTI_TOOL_MODEL", multi_tool_model)

        # R127.A — per-tool LLM provider routing.
        # `base_config` is the project's LLMConfig (introduced by R127.A so
        # tool-specific overrides can resolve via `tool_overrides`). When None,
        # `_client_for_tool` falls back to `self._client` (existing behavior;
        # zero-impact backward compatibility for callers that haven't migrated).
        # `tool_client_cache` is a dict keyed on (provider_value, model) that
        # ARTA passes per gen request so all reqs in a batch share constructed
        # clients (cheap, but the LiteLLM adapter builds a proxy that's worth
        # reusing).
        self._base_config = base_config
        self._tool_client_cache: dict = tool_client_cache if tool_client_cache is not None else {}

        # R127.C — escalation counter for per-batch cap enforcement. Atomic
        # increment via _r127_c_escalations_lock (R127.B.2) when parallel
        # sub-req gen runs concurrently. Counter is per-agent-instance →
        # naturally per-batch since one agent is shared across all reqs in
        # a gen request (per tests.py:2061).
        self._r127_c_escalations_count: int = 0
        # R127.E.3 — per-req counter is reset at the start of each
        # _r127_b_generate_decomposed invocation so a dense req's 16 subs
        # can all be escalation-eligible without exhausting siblings'
        # budget. Both counters are checked atomically; whichever cap is
        # reached first produces a differentiated outcome (capped_batch
        # vs capped_req).
        self._r127_c_escalations_count_this_req: int = 0
        import asyncio as _asyncio_init
        self._r127_c_escalations_lock = _asyncio_init.Lock()

        # D3: Provider-aware timeouts. Anthropic-hosted Sonnet typically returns
        # combined multi-tool in 60-90s (180s SLA). Local Ollama 32B Q4-Q8 needs
        # 3-7 minutes on a single GPU; cap higher to avoid premature kills.
        # NOTE: these attributes are currently unconsumed by the gen path
        # (no asyncio.wait_for in this class reads them). The actual
        # outer-timeout lives at api/routers/tests.py:_outer_auto_timeout
        # which is fixed by R131.A (see that file for the upstream-most
        # per-project-aware timeout-selection fix).
        import os as _os
        _provider = _os.environ.get("ARTA_LLM_PROVIDER", "anthropic").lower()
        _is_local = _provider in ("ollama",)
        self._combined_timeout = 600.0 if _is_local else 180.0
        self._single_timeout_long = 300.0 if _is_local else 90.0   # playwright/selenium/cypress/appium
        self._single_timeout_short = 240.0 if _is_local else 60.0  # newman/k6/zap

        # Per-tool failure reasons from the most recent generate() invocation.
        # Populated by batch/sequential paths; callers (tests.py _generate_all_background)
        # read this to surface the actual cause (truncation / timeout / rate_limit /
        # content_invalid) in the job results modal instead of a generic string.
        self._last_tool_errors: dict[str, str] = {}

        # R127.B/C — per-tool metadata side-channel.
        # `generate()` returns a {filename: content} dict, which drops the
        # AutomationScript.metadata field. Callers (tests.py) read this side
        # channel to merge gen-time telemetry (r127_b_decomposed,
        # r127_c_escalated, etc.) into the persisted test row's
        # `_gen_metrics`. Keyed by tool name (e.g. "playwright") since one
        # generate() call typically produces one script per tool.
        self._last_script_metadata: dict[str, dict] = {}

        # R104.B — agent-owned MCP connections. Lifecycle = agent lifecycle.
        # `connect_mcp()` is lazy + idempotent (called on first need). The
        # AutomationEngineerAgent currently uses `github` MCP for source-code
        # context during PW gen (R104.B); other MCPs can be added here later.
        # Pre-R104.B every github_context.py helper spawned its own
        # github-mcp-server subprocess via stdio JSON-RPC, connected,
        # called one tool, disconnected — high overhead + no shared state.
        # Post-R104.B the agent owns the connection persistently.
        self._mcp_clients: dict[str, object] = {}
        self._mcp_connected: bool = False

    # ── R127.A — per-tool client resolution ───────────────────────────────────

    def _client_for_tool(self, tool_name: str):
        """R127.A — return the LLM client to use for *tool_name*.

        When `self._base_config` is None or the project has no override for
        *tool_name*, returns `self._client` (object identity preserved →
        zero-allocation fast path, current behavior). When an override IS
        present, returns the cached/constructed tool-specific client.

        Synchronous variant used by the existing sequential per-tool gen
        path. For R127.B.2 (parallel sub-req gen), `_client_for_tool_async`
        is the concurrent-safe version.
        """
        if self._base_config is None:
            return self._client
        try:
            from .llm_client import resolve_tool_client
            return resolve_tool_client(
                self._base_config, tool_name, self._tool_client_cache,
            )
        except Exception:
            # Defensive: never break existing per-tool gen on resolver bugs.
            # Falls back to the agent's base client (current behavior).
            return self._client

    async def _client_for_tool_async(self, tool_name: str):
        """R127.B.2 — concurrent-safe variant of `_client_for_tool`.

        Used inside `asyncio.gather`-wrapped per-sub-req loops. The fast
        path (cache hit) takes no lock; on miss the module-level resolver
        lock guards client construction so two coroutines don't both
        construct the same underlying client.
        """
        if self._base_config is None:
            return self._client
        try:
            from .llm_client import resolve_tool_client_async
            return await resolve_tool_client_async(
                self._base_config, tool_name, self._tool_client_cache,
            )
        except Exception:
            return self._client

    # ── R127.C — escalation counter helpers (atomic under R127.B.2) ──────────

    async def _r127_c_try_reserve_escalation_slot(self) -> bool:
        """R127.C + R127.B.2 + R127.E.3 — atomic check-and-increment.

        Returns True when the caller has reserved one slot from BOTH the
        per-batch and per-req escalation budgets; False when EITHER cap
        is reached. Atomic via `_r127_c_escalations_lock` so concurrent
        sub-req gen calls (R127.B.2) cannot both pass the cap-check then
        both increment past the limit.

        Callers that need to know WHICH cap was hit should call
        `_r127_c_capped_kind()` immediately after a False return —
        it reads the same locked state without mutating it.
        """
        async with self._r127_c_escalations_lock:
            cap_batch_attr = getattr(self._base_config, "escalation_cap", None)
            cap_batch = int(cap_batch_attr) if cap_batch_attr is not None else 10
            cap_req_attr = getattr(self._base_config, "escalation_cap_per_req", None)
            cap_req = int(cap_req_attr) if cap_req_attr is not None else 10
            if self._r127_c_escalations_count >= cap_batch:
                return False
            if self._r127_c_escalations_count_this_req >= cap_req:
                return False
            self._r127_c_escalations_count += 1
            self._r127_c_escalations_count_this_req += 1
            return True

    async def _r127_c_capped_kind(self) -> str:
        """R127.E.3 — returns which cap was hit on the most recent
        try_reserve failure: 'batch' (per-batch ceiling reached), 'req'
        (per-req ceiling reached), or 'none' (no cap hit; caller should
        not be invoking this).

        Read-only (no counter mutation). Atomic under the same lock so
        the answer is consistent with what try_reserve just saw.
        """
        async with self._r127_c_escalations_lock:
            cap_batch_attr = getattr(self._base_config, "escalation_cap", None)
            cap_batch = int(cap_batch_attr) if cap_batch_attr is not None else 10
            cap_req_attr = getattr(self._base_config, "escalation_cap_per_req", None)
            cap_req = int(cap_req_attr) if cap_req_attr is not None else 10
            if self._r127_c_escalations_count >= cap_batch:
                return "batch"
            if self._r127_c_escalations_count_this_req >= cap_req:
                return "req"
            return "none"

    async def _r127_c_reset_per_req_counter(self) -> None:
        """R127.E.3 — reset the per-req escalation counter at the start
        of each decomposed gen invocation so each req gets a fresh
        budget. Atomic under the same lock so a concurrent sub-req
        cannot observe a half-reset state.
        """
        async with self._r127_c_escalations_lock:
            self._r127_c_escalations_count_this_req = 0

    async def _r130_d_reset_batch_counter(self) -> None:
        """R130.D — reset the per-batch escalation counter when entering
        a new req's decomposed gen invocation.

        Pre-R130.D: `_r127_c_escalations_count` was per-agent-instance
        and never reset → the batch's last req FAILED at 1887.5s because earlier
        reqs consumed escalations and the batch cap (10/10)
        was hit mid-req. Per-req counter reset (R127.E.3) only
        helped within a single req, not across reqs in the same batch.

        Post-R130.D: each req gets a fresh batch budget. The "per-batch"
        cap is now effectively per-req-within-batch — which is what the
        original R127.C contract intended.

        Atomic under the same lock as the counter mutators so a concurrent
        sub-req cannot observe a half-reset state.
        """
        async with self._r127_c_escalations_lock:
            self._r127_c_escalations_count = 0

    def _r127_c_escalation_threshold(self) -> float:
        """R127.C — current per-batch quality threshold (default 0.5)."""
        thr = getattr(self._base_config, "escalation_threshold", None)
        return float(thr) if thr is not None else 0.5

    def _r127_c_escalation_client_for_tool(self, tool_name: str):
        """R127.C — return the escalation client for *tool_name* OR None.

        Reads the `<tool_name>_escalation` key in `tool_overrides` via the
        R127.A resolver. When no escalation override is configured for
        this tool, returns None (no escalation possible; the caller falls
        through to R102.A stamping as the existing truthful BLOCK path).

        NEVER silent: the caller MUST log every escalation event so the
        R125.I dashboard surfaces it (R127.C anti-fallback contract).
        """
        if self._base_config is None:
            return None
        override_key = f"{tool_name}_escalation"
        overrides = getattr(self._base_config, "tool_overrides", None) or {}
        if override_key not in overrides:
            return None
        try:
            from .llm_client import resolve_tool_client
            return resolve_tool_client(
                self._base_config, override_key, self._tool_client_cache,
            )
        except Exception:
            return None

    async def connect_mcp(self, project: dict | None = None) -> None:
        """R104.B — establish persistent MCP connections owned by this agent.

        Idempotent: re-entry is a no-op. Called lazily on first gen-call OR
        explicitly at agent setup. Graceful: failures log + clear the
        registry so callers fall back to existing pre-R104 paths
        (captured_endpoints, DOM catalog, etc.).
        """
        if self._mcp_connected:
            return
        try:
            from .github_context import GitHubMCPClient
            _project = project or {}
            _integrations = _project.get("integrations") or {}
            if hasattr(_integrations, "model_dump"):
                _integrations = _integrations.model_dump()
            _token = (
                _integrations.get("github_token")
                or __import__("os").environ.get("GITHUB_TOKEN", "")
            )
            if not _token:
                log.debug(
                    "R104.B: GITHUB_TOKEN unavailable; PW gen will skip "
                    "SUT source context (graceful degradation to R98.3 only).",
                )
                self._mcp_connected = True   # mark connected to avoid retries
                return
            client = GitHubMCPClient(_token)
            await client.start()
            self._mcp_clients["github"] = client
            self._mcp_connected = True
            log.info(
                "R104.B: AutomationEngineerAgent connected GitHub MCP "
                "(persistent client; will be reused across all PW gen "
                "calls for this agent instance)",
            )
        except Exception as exc:
            log.warning(
                "R104.B: GitHub MCP connect failed (PW gen falls back to "
                "R98.3 captured_endpoints only): %s", exc,
            )
            self._mcp_connected = True   # mark to avoid retry loop

    async def _r104_b_extract_backend_routes_rest(
        self,
        project: dict,
        token: str,
        gherkin_text: str = "",
        max_routes: int = 120,
    ) -> list[dict]:
        """R104.B — extract backend route declarations via direct GitHub
        REST Search API. Returns list of `{method, path}` dicts.

        Uses the same REST-direct path that extract_frontend_routes()
        proved works (httpx + GitHub /search/code endpoint). Search query
        targets common framework patterns; client-side regex extracts
        (method, path) tuples from match snippets.

        Returns [] gracefully on any failure (rate limit, repo-not-found,
        empty result) — PW gen continues with R98.3 captured_endpoints.
        """
        # A1 (2026-07-25) — default to the BRANCH-AWARE git-tree walk. GitHub
        # /search/code (the legacy path below) indexes ONLY the repo's DEFAULT
        # branch, so a SUT whose backend code lives on a non-default branch
        # backend routes → weak PW/Newman grounding. The tree walk honours each
        # repo_entry's configured `branch` (same pattern as extract_frontend_routes
        # + _discover_refresh_routes_rest). Killswitch restores the search path.
        if os.environ.get("ARTA_A1_BACKEND_TREE_DISABLE") != "1":
            try:
                _tree_routes = await self._r104_b_extract_via_tree(
                    project, token, gherkin_text, max_routes)
                if _tree_routes:
                    return _tree_routes
                log.debug("R104.B A1: tree walk found 0 routes — "
                          "falling back to /search/code")
            except Exception as _a1exc:
                log.warning("R104.B A1: tree walk error (%s) — "
                            "falling back to /search/code", _a1exc)
        import httpx
        import re as _re
        integrations = project.get("integrations") or {}
        if hasattr(integrations, "model_dump"):
            integrations = integrations.model_dump()
        repos = integrations.get("repositories") or []
        if not repos:
            return []
        # R107.B — `text_matches` requires the v3.text-match Accept header.
        # Without it, search/code responses omit text_matches entirely →
        # client-side regex sees empty snippets → 0 backend routes
        # extracted. Live evidence: every smoke pre-R107 had 0 R104.B
        # backend-route signal even though /search/code returned hits.
        headers = {
            "Authorization": f"token {token}",
            "Accept": (
                "application/vnd.github.v3.text-match+json, "
                "application/vnd.github.v3+json"
            ),
        }
        # Search patterns: keyword query + client-side regex extract.
        # R107.C — GitHub /search/code strips `@.` punctuation during
        # tokenization, so "@app.post" matches 0 documents. Use plain
        # tokens that tokenize correctly. Live evidence: `router.post`
        # returns 1 hit on pipeline-api (the FastAPI handler file);
        # `@app.post` returned 0 from the same repo.
        # R197 — DEDUPE the search queries. Pre-R197 there were 4 entries but 3
        # used the IDENTICAL FastAPI regex (only the GitHub query keyword
        # differed), so each repo cost 4 /search/code calls against the hard
        # 30/min search rate limit → 8 repos × 4 = 32 > 30 → the uncached
        # yielded routes — the literal "ARTA only walks one repo". Two distinct
        # queries (`router.post` for FastAPI/APIRouter files, `app.post` for
        # Express) suffice because the regex extracts ALL verbs once a route file
        # is matched. 2 queries × 14 repos = 28 ≤ 30 → ALL repos covered per run.
        _ROUTE_RE = _re.compile(
            r'@?(?:app|router)\.(get|post|put|patch|delete|head|options)\(\s*["\']([^"\']+)["\']',
            _re.IGNORECASE)
        searches = [
            ("router.post", _ROUTE_RE),   # FastAPI / APIRouter
            ("app.post", _ROUTE_RE),      # Express / FastAPI app
        ]
        out: list[dict] = []
        seen: set[tuple[str, str]] = set()
        # R105.A — cache the /search/code calls per (repo, query_kw)
        from .github_context import _r105_a_cache_get, _r105_a_cache_set, _r105_a_cache_key
        # R197 — scan ALL configured repos (was repos[:8]). With the dedupe to 2
        # so the dataset/app/agent-token/launch + analytics-consumer repos
        # (positions 9-14) are finally reached. Env-overridable cap.
        from .github_context import _gh_repo_cap as _r197_cap
        async with httpx.AsyncClient(timeout=20, headers=headers) as client:
            for repo_entry in repos[:_r197_cap()]:
                repo = repo_entry.get("repo", "") if isinstance(repo_entry, dict) else ""
                if not repo:
                    continue
                for query_kw, regex in searches:
                    try:
                        # R105.A — cache the search/code response per (repo, q)
                        _search_key = _r105_a_cache_key(repo, "search_code", query_kw)
                        _cached_body = _r105_a_cache_get(_search_key)
                        if _cached_body is not None:
                            import json as _json_r105
                            items = _json_r105.loads(_cached_body).get("items", [])
                        else:
                            resp = await client.get(
                                "https://api.github.com/search/code",
                                params={"q": f"{query_kw} repo:{repo}", "per_page": 60},  # R199 — more route files (was 30)
                            )
                            if resp.status_code != 200:
                                # Don't cache rate-limit/error responses — re-try
                                # on next call to give the API time to recover
                                continue
                            # R107.B — also skip caching empty-result responses
                            # (total_count == 0) since they're often a sign of
                            # missing Accept header or transient miss rather than
                            # a stable "no matches" outcome. Caching empties for
                            # 24h would poison the lookup for the same query.
                            try:
                                _body_preview = resp.json() or {}
                                if int(_body_preview.get("total_count") or 0) == 0:
                                    items = []
                                    continue
                            except Exception:
                                pass
                            _r105_a_cache_set(_search_key, resp.text)
                            items = (resp.json() or {}).get("items", [])
                        for item in items[:60]:  # R199 — scan more matched files (was 30)
                            # R107.B — try text_matches first (now populated
                            # post-Accept-header fix). When empty (legacy
                            # cached entries), fall back to fetching the file
                            # content directly + running regex against it.
                            # R198 — ALWAYS take the rich file-fetch path below
                            # (not the text_matches snippet) so EVERY route gets
                            # body_schema_source + auth + protocol extracted from
                            # the FULL handler file. Pre-R198 the text_matches
                            # path appended {method,path} ONLY and the `seen`
                            # dedup then LOCKED those routes minimal → no body
                            # schema → empty data_dependencies → R195 pipeline
                            # never fired. The snippet fragment can't carry the
                            # request model (it lives elsewhere in the file).
                            # Files are R105.A-cached (24h) so the extra content
                            # fetches are bounded + reused across the batch.
                            matched = False
                            if not matched:
                                fpath = item.get("path") or ""
                                repo_full = (item.get("repository") or {}).get(
                                    "full_name") or repo
                                if fpath:
                                    _f_key = _r105_a_cache_key(repo_full, "main", "content", fpath)
                                    _f_cached = _r105_a_cache_get(_f_key)
                                    try:
                                        if _f_cached:
                                            file_content = _f_cached
                                        else:
                                            fresp = await client.get(
                                                f"https://api.github.com/repos/{repo_full}/contents/{fpath}",
                                            )
                                            if fresp.status_code != 200:
                                                file_content = ""
                                            else:
                                                import base64 as _b64
                                                file_content = _b64.b64decode(
                                                    (fresp.json() or {}).get("content", "")
                                                ).decode("utf-8", errors="replace")
                                                _r105_a_cache_set(_f_key, file_content)
                                        for m in regex.finditer(file_content):
                                            method = m.group(1).upper()
                                            path = m.group(2)
                                            if not path.startswith("/"):
                                                continue
                                            key = (method, path)
                                            if key in seen:
                                                continue
                                            seen.add(key)
                                            # R156.A.1 — extract typed body
                                            # schema snippet from handler sig
                                            _body_hint = None
                                            try:
                                                _body_hint = self._r156_a_extract_body_schema_hint(
                                                    file_content, m.end(),
                                                )
                                            except Exception:
                                                pass
                                            # R156.A.2 — extract auth-decorator
                                            # chain + heuristic token_kind
                                            _auth_req = None
                                            try:
                                                _auth_req = self._r156_a_2_extract_auth_requirement(
                                                    file_content, m.start(), m.end(),
                                                )
                                            except Exception:
                                                pass
                                            # R156.C.1 — classify route protocol
                                            # (rest/grpc/sse/websocket/graphql)
                                            _protocol = "rest"
                                            try:
                                                _protocol = self._r156_c_1_classify_route_protocol(
                                                    file_content, m.start(), m.end(),
                                                )
                                            except Exception:
                                                pass
                                            _route_entry: dict = {
                                                "method": method, "path": path,
                                                "protocol": _protocol,
                                            }
                                            if _body_hint:
                                                _route_entry["body_schema_source"] = _body_hint
                                                _route_entry["body_schema_source_file"] = fpath
                                            if _auth_req:
                                                _route_entry["auth_requirement"] = _auth_req
                                            out.append(_route_entry)
                                            if len(out) >= max_routes * 3:
                                                break
                                    except Exception:
                                        pass
                            if len(out) >= max_routes * 3:
                                break
                    except Exception as exc:
                        log.debug(
                            "R104.B: REST search %s in %s failed: %s",
                            query_kw, repo, exc,
                        )
                    if len(out) >= max_routes * 3:
                        break
                if len(out) >= max_routes * 3:
                    break
        # Relevance-rank by Gherkin keyword overlap (cheap heuristic)
        if gherkin_text and out:
            _gw = {w.lower() for w in __import__("re").findall(r"\w+", gherkin_text) if len(w) >= 4}
            def _score(r):
                pw = set(__import__("re").findall(r"\w+", r.get("path") or ""))
                return sum(1 for w in pw if w.lower() in _gw)
            out.sort(key=_score, reverse=True)
        return out[:max_routes]

    def _r104_b_routes_from_content(
        self, file_content: str, fpath: str, regex, seen: set, out: list,
        max_routes: int,
    ) -> bool:
        """A1 — extract (method, path) routes + R156 enrichment (body-schema hint,
        auth requirement, protocol) from ONE file's full content. Appends to `out`
        (deduped via `seen`). Returns True when the out cap (max_routes*3) is reached.
        Shared by the branch-aware tree walk; the legacy /search/code path keeps its
        own inline copy (untouched fallback)."""
        for m in regex.finditer(file_content):
            method = m.group(1).upper()
            path = m.group(2)
            if not path.startswith("/"):
                continue
            key = (method, path)
            if key in seen:
                continue
            seen.add(key)
            _body_hint = None
            try:
                _body_hint = self._r156_a_extract_body_schema_hint(file_content, m.end())
            except Exception:
                pass
            _auth_req = None
            try:
                _auth_req = self._r156_a_2_extract_auth_requirement(
                    file_content, m.start(), m.end())
            except Exception:
                pass
            _protocol = "rest"
            try:
                _protocol = self._r156_c_1_classify_route_protocol(
                    file_content, m.start(), m.end())
            except Exception:
                pass
            _route_entry: dict = {"method": method, "path": path, "protocol": _protocol}
            if _body_hint:
                _route_entry["body_schema_source"] = _body_hint
                _route_entry["body_schema_source_file"] = fpath
            if _auth_req:
                _route_entry["auth_requirement"] = _auth_req
            out.append(_route_entry)
            if len(out) >= max_routes * 3:
                return True
        return False

    async def _r104_b_extract_via_tree(
        self, project: dict, token: str, gherkin_text: str = "",
        max_routes: int = 120,
    ) -> list[dict]:
        """A1 (2026-07-25) — BRANCH-AWARE backend-route extraction via the GitHub
        git-tree walk (NOT /search/code, which indexes only the default branch and
        so misses SUTs whose backend lives on a non-default branch, e.g.
        `release-2.1`/`release-3.0`). Mirrors extract_frontend_routes' branch-aware
        tree+content pattern (github_context.py:842). Bounded: per-repo file cap
        (ARTA_A1_BACKEND_FILE_CAP, default 40) + git-tree truncation WARN so a
        partial scan on a huge repo is loud, not silent. Reuses R105.A caching (keyed
        by branch) + _gh_repo_cap (R196). Returns [] on any failure — caller falls
        back to the legacy /search/code path."""
        import httpx
        import base64
        import json as _json
        import re as _re
        integrations = project.get("integrations") or {}
        if hasattr(integrations, "model_dump"):
            integrations = integrations.model_dump()
        repos = integrations.get("repositories") or []
        if not repos:
            return []
        headers = {
            "Authorization": f"token {token}",
            "Accept": "application/vnd.github.v3+json",
        }
        # Same route regex the legacy path uses (FastAPI/APIRouter + Express `app`).
        _ROUTE_RE = _re.compile(
            r'@?(?:app|router)\.(get|post|put|patch|delete|head|options)\(\s*["\']([^"\']+)["\']',
            _re.IGNORECASE)
        _BACKEND_EXT = (".py", ".js", ".ts", ".jsx", ".tsx", ".cs", ".go", ".java", ".rb")
        # Name/path hints bound the content-fetch set (the regex still does the real
        # filtering — a matched non-route file just yields nothing). App-entry files
        # (main/app/server/index/Program/Startup) are included so FastAPI `app.post`
        # handlers outside a router file are still reached.
        _BACKEND_HINT = (
            "rout", "controller", "api", "handler", "endpoint", "view", "resource",
            "/main.", "/app.", "/server.", "/index.", "program.cs", "startup.cs",
        )

        def _is_backend_file(p: str) -> bool:
            pl = p.lower()
            if any(x in pl for x in (
                "node_modules", "/test", ".test.", ".spec.", "/migrations/",
                "__tests__", "/tests/",
            )):
                return False
            if not pl.endswith(_BACKEND_EXT):
                return False
            return any(h in pl for h in _BACKEND_HINT)

        from .github_context import (
            _r105_a_cache_get, _r105_a_cache_set, _r105_a_cache_key,
            _gh_repo_cap as _r196_cap,
        )
        _file_cap = int(os.environ.get("ARTA_A1_BACKEND_FILE_CAP", "40"))
        out: list[dict] = []
        seen: set[tuple[str, str]] = set()
        _repos_scanned = 0
        async with httpx.AsyncClient(timeout=20, headers=headers) as client:
            for repo_entry in repos[:_r196_cap()]:
                repo = repo_entry.get("repo", "") if isinstance(repo_entry, dict) else ""
                branch = (repo_entry.get("branch", "main")
                          if isinstance(repo_entry, dict) else "main") or "main"
                if not repo:
                    continue
                try:
                    _tree_key = _r105_a_cache_key(repo, branch, "tree")
                    _tree_cached = _r105_a_cache_get(_tree_key)
                    if _tree_cached:
                        _tj = _json.loads(_tree_cached)
                    else:
                        resp = await client.get(
                            f"https://api.github.com/repos/{repo}/git/trees/{branch}",
                            params={"recursive": "1"})
                        if resp.status_code != 200:
                            log.debug("R104.B A1: tree %s@%s -> %d",
                                      repo, branch, resp.status_code)
                            continue
                        _r105_a_cache_set(_tree_key, resp.text)
                        _tj = resp.json()
                    tree = _tj.get("tree", []) if isinstance(_tj, dict) else []
                    if isinstance(_tj, dict) and _tj.get("truncated"):
                        log.warning(
                            "R104.B A1: git tree for %s@%s TRUNCATED — backend-route "
                            "scan is PARTIAL for this repo (>100k entries / 7MB)",
                            repo, branch)
                    _repos_scanned += 1
                    route_files = [
                        it["path"] for it in tree
                        if it.get("type") == "blob"
                        and _is_backend_file(it.get("path", ""))
                    ][:_file_cap]
                    _capped = False
                    for fpath in route_files:
                        try:
                            _f_key = _r105_a_cache_key(repo, branch, "content", fpath)
                            _f_cached = _r105_a_cache_get(_f_key)
                            if _f_cached is not None:
                                file_content = _f_cached
                            else:
                                fresp = await client.get(
                                    f"https://api.github.com/repos/{repo}/contents/{fpath}",
                                    params={"ref": branch})
                                if fresp.status_code != 200:
                                    continue
                                file_content = base64.b64decode(
                                    (fresp.json() or {}).get("content", "")
                                ).decode("utf-8", errors="replace")
                                _r105_a_cache_set(_f_key, file_content)
                            if self._r104_b_routes_from_content(
                                    file_content, fpath, _ROUTE_RE, seen, out, max_routes):
                                _capped = True
                                break
                        except Exception:
                            continue
                    if _capped or len(out) >= max_routes * 3:
                        break
                except Exception as exc:
                    log.debug("R104.B A1: tree walk %s failed: %s", repo, exc)
                    continue
        if gherkin_text and out:
            _gw = {w.lower() for w in _re.findall(r"\w+", gherkin_text) if len(w) >= 4}
            out.sort(
                key=lambda r: sum(
                    1 for w in _re.findall(r"\w+", r.get("path") or "")
                    if w.lower() in _gw),
                reverse=True)
        log.info("R104.B A1: branch-aware tree walk extracted %d backend routes "
                 "from %d repo(s)", len(out), _repos_scanned)
        return out[:max_routes]

    # ── R156.A.1 — Pydantic/Joi/Zod body schema extraction ────────────────
    #
    # Walks the handler function signature immediately after a route
    # decorator match, identifies a typed body parameter (FastAPI:
    # `def create_X(payload: SomeModel)`, Express+TS:
    # `(req: Request<{}, {}, SomeBody>)`), then searches the SAME file
    # for the class/interface definition and returns its raw source
    # snippet. The LLM gen prompt receives the snippet verbatim and
    # extracts field names/types itself — far more robust than
    # structurally parsing every Pydantic / TypeScript dialect.
    #
    # Mission contract: closes Iter 11's body-field hallucination
    # cluster (~171 × Newman 400 + significant fraction of 500). Without
    # this, R143.C body-field validator has only `response_body_shape`
    # (post-R150.A) to ground against — request body grounding was
    # implicit-only. R156.A.1 provides explicit request body schema
    # truth from SUT source.

    _R156_A_NON_BODY_TYPE_NAMES = frozenset({
        # FastAPI parameter helpers (path/query/header/cookie + Form/File/Body)
        "Request", "Response", "Path", "Query", "Header", "Cookie", "Body",
        "Form", "File", "Security", "Depends",
        # Common base classes / non-payload types
        "BaseModel", "BaseSettings", "Session", "Connection", "Client",
        "Annotated", "Optional", "List", "Dict", "Any", "Union",
        # Express common-non-body
        "NextFunction",
    })

    @staticmethod
    def _r156_a_extract_body_schema_hint(
        file_content: str, route_match_end: int,
    ) -> str | None:
        """R156.A.1 — return the raw Pydantic/TS-interface class/interface
        source snippet for the typed body param of the handler that
        follows ``route_match_end`` (byte position right after the route
        decorator regex match). Returns None when no body type or
        definition is found.

        Implementation notes:
        - Walks at most 1500 chars after the decorator match looking for
          the handler signature ``def <name>(<args>)``. Tolerates async.
        - Identifies the first PascalCase-typed param that is NOT in
          ``_R156_A_NON_BODY_TYPE_NAMES`` (path/query/header helpers).
        - Searches the same file for ``class <Name>(...):`` (Pydantic)
          OR ``interface <Name>`` / ``type <Name> = {`` (TS). Returns
          the class/interface body up to the first non-indented line
          (capped at 30 lines).
        - Defensive: regex-only; no AST parsing; tolerates malformed
          source by returning None.
        """
        import re as _re_r156_a
        # Window after the decorator match — handler signature lives here
        next_section = file_content[route_match_end:route_match_end + 1500]
        # FastAPI/Express handler signature: find `def <name>(` or
        # `async def <name>(` and accumulate text balanced-paren-style
        # until we hit the matching close-paren. Multi-line signatures
        # with nested parens like `user_id: str = Path(...)` would break
        # a naive `\(([^)]*)\)` match — the first `)` inside `Path(...)`
        # closes the outer group prematurely.
        def_re = _re_r156_a.compile(r"(?:async\s+)?def\s+\w+\s*\(")
        def_match = def_re.search(next_section)
        if not def_match:
            return None
        # Walk forward from the `(` finding the balanced close `)`
        i = def_match.end()           # position right after the opening `(`
        depth = 1
        sig_start = i
        while i < len(next_section) and depth > 0:
            ch = next_section[i]
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            i += 1
        if depth != 0:
            # Unbalanced — signature truncated past our 1500-char window
            return None
        sig_end = i - 1   # position of the matching `)`
        arg_list = next_section[sig_start:sig_end]
        # Walk each typed arg looking for `<name>: <PascalCaseType>`
        param_re = _re_r156_a.compile(
            r"(\w+)\s*:\s*([A-Z]\w+)",
        )
        model_name: str | None = None
        for arg_m in param_re.finditer(arg_list):
            cand = arg_m.group(2)
            if cand in AutomationEngineerAgent._R156_A_NON_BODY_TYPE_NAMES:
                continue
            # Skip qualified types like fastapi.Body
            if "." in cand:
                continue
            model_name = cand
            break
        if not model_name:
            return None
        # Search file for class/interface definition
        # Pydantic / Python: `class Name(BaseModel):` or `class Name(Some):`
        class_re = _re_r156_a.compile(
            rf"class\s+{_re_r156_a.escape(model_name)}\s*\([^)]*\)\s*:",
        )
        # TypeScript: `interface Name {` or `type Name = {`
        ts_iface_re = _re_r156_a.compile(
            rf"(?:interface\s+{_re_r156_a.escape(model_name)}\s*\{{|"
            rf"type\s+{_re_r156_a.escape(model_name)}\s*=\s*\{{)",
        )
        cm = class_re.search(file_content) or ts_iface_re.search(file_content)
        if not cm:
            return None
        # Extract the class/interface body — walk lines from match start
        # until we hit a non-indented (col 0) line that isn't blank.
        rest = file_content[cm.start():]
        lines = rest.split("\n")
        snippet_lines: list[str] = [lines[0]]   # the `class X:` / `interface X {` line
        brace_depth = lines[0].count("{") - lines[0].count("}")
        is_ts = "interface" in lines[0] or " = {" in lines[0]
        for ln in lines[1:30]:   # cap at 30 lines for class body
            if is_ts:
                # TypeScript: stop when matching close-brace reaches depth 0
                brace_depth += ln.count("{") - ln.count("}")
                snippet_lines.append(ln)
                if brace_depth <= 0:
                    break
            else:
                # Python: stop on first non-indented non-blank line
                if ln.strip() == "":
                    snippet_lines.append(ln)
                    continue
                if ln.startswith(" ") or ln.startswith("\t"):
                    snippet_lines.append(ln)
                else:
                    break
        snippet = "\n".join(snippet_lines).rstrip()
        return snippet or None

    # ── R156.A.2 — Auth-decorator extraction (token-kind classifier) ──
    #
    # Walks a window around each route match (5 lines before for stacked
    # decorators + 30 lines after for `dependencies=[...]` inline args + the
    # function body) and extracts the auth-decorator chain. Heuristic-maps
    # decorator/middleware names to canonical token_kind via
    # `_R156_A_2_TOKEN_KIND_HINTS`.
    #
    # Mission contract (Pillar 2): supersedes R98.2's hardcoded domain-
    # prefix routing with per-endpoint source-derived classification.
    # Post-R156.A.2: each route carries explicit token_kind sourced from
    # the SUT's actual decorator chain.

    # Heuristic name → token_kind map. Ordered: more-specific first
    _R156_A_2_TOKEN_KIND_HINTS: tuple[tuple[str, str], ...] = (
        # collide with the agent_token bucket
        ("session_token", "session_token"),
        # AWS / S3 — temp creds + presigned URLs
        ("aws_temp_cred", "aws_temp_creds"),
        ("aws_cred", "aws_temp_creds"),
        ("temp_cred", "aws_temp_creds"),
        ("aws_sts", "aws_temp_creds"),
        ("s3_presigned", "s3_presigned"),
        ("presigned", "s3_presigned"),
        ("agent_token", "agent_token"),
        ("agent_api", "agent_token"),
        ("jwt", "agent_token"),
        ("bearer", "agent_token"),
        # Generic auth markers (catch-all for verify_X / requires_X / authenticated)
        ("verify_token", "agent_token"),
        ("verify_auth", "agent_token"),
        ("verify_user", "agent_token"),
        ("requires_auth", "agent_token"),
        ("requires_login", "agent_token"),
        ("authenticated", "agent_token"),
        ("authorize", "agent_token"),
        ("get_current_user", "agent_token"),
        ("current_user", "agent_token"),
    )

    @staticmethod
    def _r156_a_2_classify_token_kind(decorator_name: str) -> str | None:
        """Map a decorator/middleware name to a canonical token_kind from
        `_R156_A_2_TOKEN_KIND_HINTS`. Returns None when no hint matches —
        caller treats that as `auth_requirement.token_kind="none"` (no
        auth required) OR falls back to R98.2 domain-prefix routing as
        backstop."""
        if not decorator_name:
            return None
        lower = decorator_name.lower()
        for needle, kind in AutomationEngineerAgent._R156_A_2_TOKEN_KIND_HINTS:
            if needle in lower:
                return kind
        return None

    @staticmethod
    def _r156_a_2_extract_auth_requirement(
        file_content: str, route_match_start: int, route_match_end: int,
    ) -> dict | None:
        """R156.A.2 — return auth_requirement dict for the handler that
        owns this route, or None when no auth decorator is detected.

        Inspection window:
          - 5 lines BEFORE the route match for stacked decorators
            (`@requires_auth\n@router.post(...)`)
          - 30 lines AFTER the route match for inline `dependencies=[...]`
            arg + handler body (Express positional-middleware case)

        Detected patterns:
          - FastAPI: `Depends(<name>)`, `Security(<name>, scopes=[...])`
          - Stacked decorator: `@<name>` lines preceding the route
          - NestJS: `@UseGuards(<name>)`
          - Express positional: `app.get('/x', <middleware>, handler)`

        Output shape:
          {
            "token_kind": "agent_token" | "<root-session-token kind>" | "aws_temp_creds"
                          | "s3_presigned" | "none",
            "scopes": [...],
            "decorator_chain": ["verify_agent_token", ...],
            "source_evidence": "<line_number>",  # 1-indexed
          }
        """
        import re as _re_r156_a2
        # Build the inspection window: 5 lines BEFORE + 30 lines AFTER
        # the route match. We measure "lines before" by walking backward
        # from route_match_start through newlines.
        before_start = route_match_start
        nlines = 0
        while before_start > 0 and nlines < 5:
            before_start -= 1
            if file_content[before_start] == "\n":
                nlines += 1
        # 30 lines after the route match
        window = file_content[before_start:route_match_end + 2500]
        # Pattern 1: FastAPI Depends(X) / Security(X)
        depends_re = _re_r156_a2.compile(
            r"\b(?:Depends|Security)\s*\(\s*([A-Za-z_]\w*)",
        )
        # Pattern 2: NestJS @UseGuards(X) — single guard OR comma-separated
        guards_re = _re_r156_a2.compile(
            r"@UseGuards\s*\(\s*([^)]+)\)",
        )
        # Pattern 3: stacked Python decorator `@<name>` (skip @router/@app
        # to avoid matching the route decorator itself + common non-auth
        # decorators like @staticmethod / @classmethod / @cached)
        stacked_re = _re_r156_a2.compile(
            r"^\s*@([a-zA-Z_]\w*)\b",
            _re_r156_a2.MULTILINE,
        )
        # Pattern 4: Security(X, scopes=["a", "b"])
        scopes_re = _re_r156_a2.compile(
            r"\bSecurity\s*\([^)]*?scopes\s*=\s*\[([^\]]*)\]",
        )

        names: list[str] = []
        # 1) Depends(X) / Security(X)
        for m in depends_re.finditer(window):
            names.append(m.group(1))
        # 2) @UseGuards(X) — split on comma for multi-guard usage
        for m in guards_re.finditer(window):
            for g in m.group(1).split(","):
                g_clean = g.strip()
                if g_clean and g_clean.isidentifier():
                    names.append(g_clean)
        # 3) stacked decorators (excluding router/app/staticmethod/classmethod
        # /property/cached_property/asynccontextmanager/contextmanager
        # and standard pytest/typing decorators we don't want to count as auth)
        _R156_A_2_SKIP_DECORATORS = {
            "router", "app", "bp", "blueprint", "staticmethod", "classmethod",
            "property", "cached_property", "asynccontextmanager",
            "contextmanager", "pytest", "fixture", "abstractmethod",
            "dataclass", "lru_cache",
        }
        for m in stacked_re.finditer(window):
            name = m.group(1)
            # Skip the route decorator itself + common Python helpers
            if name in _R156_A_2_SKIP_DECORATORS:
                continue
            # Skip if the line starts a route decorator (router.post / app.get etc.)
            # — these appear matched too if the stacked regex catches the leading `@`
            # before `router` in `@router.post(...)`. Heuristic: the next char
            # after the name in the source is `.`, indicating method access.
            _idx_in_window = m.end()
            if _idx_in_window < len(window) and window[_idx_in_window] == ".":
                continue
            names.append(name)
        # 4) Scopes (from Security(...))
        scopes: list[str] = []
        for m in scopes_re.finditer(window):
            for s in m.group(1).split(","):
                s_clean = s.strip().strip("\"'")
                if s_clean:
                    scopes.append(s_clean)

        # Deduplicate while preserving order
        seen: set[str] = set()
        decorator_chain: list[str] = []
        for n in names:
            if n and n not in seen:
                seen.add(n)
                decorator_chain.append(n)
        if not decorator_chain:
            return None

        # Heuristic-classify token_kind from the FIRST matching decorator name
        token_kind: str | None = None
        for name in decorator_chain:
            kind = AutomationEngineerAgent._r156_a_2_classify_token_kind(name)
            if kind:
                token_kind = kind
                break
        # When decorators exist but none classify (e.g., custom unknown
        # middleware), default to agent_token — auth IS required, just
        # not heuristically classifiable. Operator can override per-project.
        if token_kind is None:
            token_kind = "agent_token"

        # Compute 1-indexed line number for source_evidence
        line_number = file_content[:route_match_start].count("\n") + 1

        return {
            "token_kind": token_kind,
            "scopes": scopes,
            "decorator_chain": decorator_chain,
            "source_evidence": str(line_number),
        }

    # ── R156.I.1 — Refresh-endpoint detection ─────────────────────────
    #
    # Scans file content for routes that look like auth-refresh endpoints
    # (`/refresh`, `/auth/refresh`, `/token/refresh`, etc.) + extracts:
    #   - endpoint_path: full route URL
    #   - method: POST (refresh is always POST per OAuth/JWT convention)
    #   - request_body_field: the field name carrying refresh_token
    #     (refresh_token vs refreshToken — sourced from Pydantic class body
    #     when present, falls back to default 'refresh_token')
    #   - response_access_token_field: field name carrying new access token
    #   - response_refresh_token_field: rotation field name (None if no rotation)
    #   - response_expires_in_field: TTL signal field name
    #
    # Mission contract (Pillar 2): R156.I.2 consumes this output to build
    # TOKEN_CHAINS.refresh_flow. R156.J.1/J.2 inject auto-refresh logic
    # using these field names into generated Newman + PW scripts. Closes
    # Iter 11's agent_token-TTL-cascade class during long smokes.

    # Two-stage detection: (1) match any `@router.post("URL")` or
    # `app.post("URL")` line and capture the URL; (2) post-hoc verify
    # the URL contains a refresh-endpoint indicator. This avoids the
    # greedy multi-line trap of a single combined pattern (whose
    # `[^"']*` greedy suffix could span across multiple route handlers
    # in the same file, capturing junk like `)\nasync def refresh(...)`).
    _R156_I_1_ROUTE_URL_PATTERN: str = (
        r"@?(?:app|router)\.post\(\s*[\"']([^\"']+)[\"']"
    )
    _R156_I_1_REFRESH_PATH_INDICATOR: str = (
        # G5 (R156.I.4): also match `/refreshToken`, `/refreshAccessToken`, etc.
        # Pre-fix `/refresh(?:[/?]|$)` required a delimiter/EOL right after
        r"(?:auth/refresh|token/refresh|/refresh(?:[/?A-Za-z]|$))"
    )

    _R156_I_1_REFRESH_BODY_FIELD_NAMES: tuple[str, ...] = (
        "refresh_token", "refreshToken", "refresh", "token", "refreshKey",
    )
    _R156_I_1_RESPONSE_ACCESS_FIELDS: tuple[str, ...] = (
        "access_token", "accessToken", "auth_token", "authToken",
        "agent_token", "agentToken", "token", "bearer_token", "bearerToken",
    )
    _R156_I_1_RESPONSE_REFRESH_FIELDS: tuple[str, ...] = (
        "refresh_token", "refreshToken",
    )
    _R156_I_1_RESPONSE_EXPIRES_FIELDS: tuple[str, ...] = (
        "expires_in", "expiresIn", "exp", "ttl", "expires_at", "expiresAt",
    )

    @staticmethod
    def _r156_i_1_detect_refresh_endpoints(file_content: str) -> list[dict]:
        """R156.I.1 — return list of refresh_flow dicts for any refresh-
        endpoint detected in this file. Returns [] when none found.

        For each detected refresh route, walks the handler signature (via
        R156.A.1's body-schema helper) to find the request body field name
        carrying the refresh token. Walks the handler RETURN region to find
        response field names (access_token, refresh_token, expires_in).
        Falls back to canonical defaults when source doesn't make the
        names explicit.

        Output shape per entry:
          {
            "endpoint_path": "/api/auth/refresh",
            "method": "POST",
            "request_body_field": "refresh_token",
            "response_access_token_field": "access_token",
            "response_refresh_token_field": "refresh_token",  # None if no rotation
            "response_expires_in_field": "expires_in",        # None if absent
            "source_evidence_line": 42,  # 1-indexed
          }
        """
        import re as _re_r156_i1
        out: list[dict] = []
        seen_paths: set[str] = set()
        # Two-stage detection: match every route URL, then keep only the
        # ones whose URL contains a refresh-endpoint indicator.
        url_rex = _re_r156_i1.compile(
            AutomationEngineerAgent._R156_I_1_ROUTE_URL_PATTERN,
            _re_r156_i1.IGNORECASE,
        )
        indicator_rex = _re_r156_i1.compile(
            AutomationEngineerAgent._R156_I_1_REFRESH_PATH_INDICATOR,
            _re_r156_i1.IGNORECASE,
        )
        for m in url_rex.finditer(file_content):
            path = m.group(1)
            if not indicator_rex.search(path):
                continue
            if path in seen_paths:
                continue
            seen_paths.add(path)
            line_no = file_content[:m.start()].count("\n") + 1

            # 1) Inspect handler signature for typed body model (R156.A.1)
            request_body_field: str | None = None
            body_snippet = AutomationEngineerAgent._r156_a_extract_body_schema_hint(
                file_content, m.end(),
            )
            if body_snippet:
                # Walk the snippet for a field whose NAME matches a known
                # refresh-token field convention
                for field_name in AutomationEngineerAgent._R156_I_1_REFRESH_BODY_FIELD_NAMES:
                    # Field appears as `<field_name>:` or `<field_name> =` in Pydantic
                    field_re = _re_r156_i1.compile(
                        rf"\b{_re_r156_i1.escape(field_name)}\s*[:=]",
                    )
                    if field_re.search(body_snippet):
                        request_body_field = field_name
                        break
            # Fallback to canonical default
            if not request_body_field:
                request_body_field = "refresh_token"

            # 2) Inspect a window AFTER the route decorator (handler body)
            # for response field hints. Look 60 lines forward to cover most
            # handler bodies before hitting next route decorator.
            handler_window = file_content[m.end():m.end() + 3000]

            def _first_match(field_names: tuple[str, ...]) -> str | None:
                for fn in field_names:
                    # Matches three common shapes:
                    #   - `"<fn>":` / `'<fn>':` — quoted JSON / Pydantic key
                    #   - `<fn>:`             — unquoted JS object literal key
                    #   - `<fn>=`             — Python kwarg
                    # `\b` anchors so partial-name matches don't
                    # false-positive. Optional trailing `['"]?` covers
                    # the case `"expires_in":` where a closing quote
                    # sits between the field name and the colon.
                    if _re_r156_i1.search(
                        rf"\b{_re_r156_i1.escape(fn)}['\"]?\s*[:=]",
                        handler_window,
                    ):
                        return fn
                return None

            response_access_token_field = _first_match(
                AutomationEngineerAgent._R156_I_1_RESPONSE_ACCESS_FIELDS,
            ) or "access_token"
            response_refresh_token_field = _first_match(
                AutomationEngineerAgent._R156_I_1_RESPONSE_REFRESH_FIELDS,
            )
            response_expires_in_field = _first_match(
                AutomationEngineerAgent._R156_I_1_RESPONSE_EXPIRES_FIELDS,
            )

            out.append({
                "endpoint_path": path,
                "method": "POST",
                "request_body_field": request_body_field,
                "response_access_token_field": response_access_token_field,
                "response_refresh_token_field": response_refresh_token_field,
                "response_expires_in_field": response_expires_in_field,
                "source_evidence_line": line_no,
            })
        return out

    # ── R156.A.3 — Frontend → Backend call-graph linkage ─────────────
    #
    # R105.C already extracts api_calls from FE component files (raw URL
    # strings). R156.A.3 LINKS each FE api_call to its canonical backend
    # route entry (with body_schema_source + auth_requirement populated
    # by R156.A.1 + R156.A.2). The LLM PW prompt then sees, per FE route,
    # not just "this component calls /api/v1/datasets" but the FULL
    # backend handler context: Pydantic request body fields + token kind
    # + decorator chain + scopes.
    #
    # Mission contract (Pillar 1b): Iter 11 evidence showed PW specs
    # generating `page.waitForResponse(...)` against invented URLs even
    # though R105.C surfaced api_calls — the LLM didn't have enough
    # signal to know which calls were the load-bearing ones for the
    # scenario. R156.A.3 attaches the body_schema + auth metadata so
    # the LLM can compose assertions that match real SUT response
    # contracts.

    @staticmethod
    def _r156_a_3_normalize_path_for_match(path: str) -> str:
        """Normalize a URL path for backend-route matching:
          - Strip leading scheme/host if present
          - Replace `${var}` and `{var}` placeholders with `:` wildcard
          - Strip trailing slash + query string
        Used for FE api_call → BE route equality match."""
        import re as _re_r156_a3
        if not isinstance(path, str) or not path:
            return ""
        # Strip scheme + host if present
        path = _re_r156_a3.sub(r"^https?://[^/]+", "", path)
        # Strip query string + fragment
        path = path.split("?", 1)[0].split("#", 1)[0]
        # Strip trailing slash (except for root "/")
        if len(path) > 1 and path.endswith("/"):
            path = path[:-1]
        # Replace ${var} and {var} with a generic wildcard token
        path = _re_r156_a3.sub(r"\$\{[^}]+\}", ":wild", path)
        path = _re_r156_a3.sub(r"\{[^}]+\}", ":wild", path)
        return path

    @staticmethod
    def _r156_a_3_link_fe_to_be_routes(
        fe_routes: list[dict],
        be_routes: list[dict],
    ) -> list[dict]:
        """R156.A.3 — for each FE route's `api_calls`, find matching
        backend route entries and attach them as `api_call_links`:
          [{"url": "/api/v1/datasets", "method": "POST",
            "body_schema_source": "class DatasetCreate(BaseModel):...",
            "auth_requirement": {...}}, ...]

        Path matching is normalized-equality on the canonical path
        (placeholders → wildcard). Path-only matches (no method info
        from the api_call URL) are linked against ALL methods, but
        callers may downstream-filter.

        Returns the SAME fe_routes list, mutated in place with
        `api_call_links` field where matches exist. Routes with no
        api_calls / no matches keep their existing fields unchanged.
        """
        if not fe_routes or not be_routes:
            return fe_routes
        # Build a lookup table: normalized_path → list of be_route dicts
        # (a path may be served by multiple methods — GET + POST etc.)
        be_by_path: dict[str, list[dict]] = {}
        for br in be_routes:
            if not isinstance(br, dict):
                continue
            be_path = br.get("path") or ""
            norm = AutomationEngineerAgent._r156_a_3_normalize_path_for_match(be_path)
            if norm:
                be_by_path.setdefault(norm, []).append(br)

        for fr in fe_routes:
            if not isinstance(fr, dict):
                continue
            api_calls = fr.get("api_calls") or []
            if not api_calls:
                continue
            links: list[dict] = []
            for call_url in api_calls:
                norm = AutomationEngineerAgent._r156_a_3_normalize_path_for_match(call_url)
                if not norm:
                    continue
                matched_be = be_by_path.get(norm) or []
                # Also try a "/api"-prefix variant — R107.C / R143.B observed
                # that FE code sometimes references `/v1/X` while the BE route
                # is declared `/api/v1/X` (mount-prefix gap).
                if not matched_be and not norm.startswith("/api/"):
                    matched_be = be_by_path.get("/api" + norm) or []
                if not matched_be and norm.startswith("/api/"):
                    matched_be = be_by_path.get(norm[4:]) or []
                for br in matched_be:
                    link: dict = {
                        "url": call_url,
                        "method": br.get("method") or "GET",
                    }
                    if br.get("body_schema_source"):
                        link["body_schema_source"] = br["body_schema_source"]
                    if br.get("auth_requirement"):
                        link["auth_requirement"] = br["auth_requirement"]
                    links.append(link)
                # Cap per-FE-route links at 8 to keep prompt budget bounded
                if len(links) >= 8:
                    break
            if links:
                fr["api_call_links"] = links
        return fe_routes

    @staticmethod
    def _r211_flatten_code_api_links(fe_routes: list[dict]) -> list[dict]:
        """R211 B3.3 — STOP DISCARDING the Code→API evidence. Flatten the FE→BE
        `api_call_links` (computed by `_r156_a_3_link_fe_to_be_routes`, then
        previously thrown away after prompt rendering) into a compact list the
        caller surfaces onto `risk["_code_api_links"]` → test metadata + the
        graph `FrontendRoute-[:INVOKES]->Endpoint` edge."""
        flat: list[dict] = []
        for fr in (fe_routes or []):
            if not isinstance(fr, dict):
                continue
            route = fr.get("route") or fr.get("path") or ""
            for lk in (fr.get("api_call_links") or []):
                _m = (lk.get("method") or "GET").upper()
                _u = lk.get("url") or ""
                flat.append({
                    "fe_route": route,
                    "url": _u,
                    "method": _m,
                    "endpoint_key": f"{_m}:{_u}" if _u else "",
                    "auth_requirement": (lk.get("auth_requirement") or {}),
                    "body_schema_source": lk.get("body_schema_source") or "",
                })
        return flat

    #
    # Encodes the per-SUT token-exchange topology. Each entry's `from`
    # field links to the upstream token kind; the chain root is
    # this map to compute, per endpoint, the FULL chain of hops the
    # dispatched test needs to mint before the action request.
    #
    # `ttl_min` is the canonical max lifetime (minutes); R156.I.2 will
    # decorate the `agent_token` entry with a `refresh_flow` sub-dict
    # at runtime when R156.I.1 detects a refresh endpoint in the SUT
    # source. The Newman + PW auto-refresh scripts (R156.J) consume the
    # refresh_flow sub-dict to schedule TTL-aware refreshes.

    # hardcoded-only topology: `_r156_b_1_resolve_token_chain(kind, extra_chains=)`
    # and `annotate_routes_with_token_chains(token_chains=)` both accept a
    # per-project map that EXTENDS/overrides it (architecture_discovery.py:529
    # already builds `dict(_R156_B_1_TOKEN_CHAINS)` + adds source-discovered hops),
    # platform code. Unknown kinds resolve to [] (graceful, no leak to other SUTs).
    _R156_B_1_TOKEN_CHAINS: dict[str, dict] = {
        "session_token": {
            "source": "operator_paste",
        },
        "agent_token": {
            "from": "session_token",
            "via": "POST /api/.../create_agent_api_token",
            "ttl_min": 60,
        },
        "aws_temp_creds": {
            "from": "agent_token",
            "via": "GET /generate-temp-creds",
            "ttl_min": 60,
        },
        "s3_presigned": {
            "from": "agent_token",
            "via": "GET /generate-presigned-url",
            "ttl_min": 5,
        },
    }

    @staticmethod
    def _r156_b_1_resolve_token_chain(
        target_token_kind: str, *, extra_chains: dict | None = None,
    ) -> list[dict]:
        """R156.B.1 — given a target token_kind (e.g., `s3_presigned`),
        return the ORDERED list of chain hops the dispatched test must
        perform before invoking the action endpoint:

            [
              {"kind": "<root-kind>", "source": "operator_paste"},
              {"kind": "agent_token", "from": "<root-kind>",
               "via": "POST /api/.../create_agent_api_token", "ttl_min": 60},
              {"kind": "s3_presigned", "from": "agent_token",
               "via": "GET /generate-presigned-url", "ttl_min": 5},
            ]

        Each hop carries its upstream `from` kind + the `via` endpoint
        that mints it. The first hop is always the root session-token kind.

        Returns [] when the target kind is unknown (caller should treat
        as "no token required" or fall back to R98.2 prefix routing).
        Defends against cycles by capping at 5 hops (the seeded chain is
        ≤3; longer indicates malformed config).

        A4 — `extra_chains` (a per-project/discovered token-chain map) EXTENDS/
        overrides the built-in seed, so any other topology resolves here too
        without editing platform code. None → seed-only (unchanged behavior).
        """
        chains = AutomationEngineerAgent._R156_B_1_TOKEN_CHAINS
        if extra_chains and isinstance(extra_chains, dict):
            chains = {**chains, **extra_chains}
        if target_token_kind not in chains:
            return []
        # Walk from target back to root, collecting hop dicts in reverse
        # order, then flip.
        hops_reverse: list[dict] = []
        cursor = target_token_kind
        seen_kinds: set[str] = set()
        for _ in range(5):
            if cursor in seen_kinds:
                # Cycle detected — bail with what we have so far
                break
            seen_kinds.add(cursor)
            entry = chains.get(cursor) or {}
            hop = {"kind": cursor}
            for k, v in entry.items():
                hop[k] = v
            hops_reverse.append(hop)
            upstream = entry.get("from")
            if not upstream:
                break
            cursor = upstream
        return list(reversed(hops_reverse))

    # ── R156.I.2 — TOKEN_CHAINS refresh_flow integration ─────────────
    #
    # Bridges R156.I.1's detected refresh endpoints into R156.B.1's
    # TOKEN_CHAINS map. R156.I.1 emits a list of refresh_flow dicts
    # (one per detected refresh endpoint); R156.I.2 picks the canonical
    # one + attaches it to the `agent_token` entry under a `refresh_flow`
    # sub-dict. Downstream R156.J.1 (Newman pre-request) + R156.J.2 (PW
    # auth_refresh.ts helper) read that sub-dict to decide whether to
    # auto-refresh + which fields to use.
    #
    # PURE FUNCTION: takes the base map + list, returns a NEW map.
    # `_R156_B_1_TOKEN_CHAINS` class-level constant is never mutated,
    # so concurrent gen calls for different projects can carry their
    # own per-SUT refresh_flow without cross-contamination.
    #
    # Mission contract: feeds R156.J's auto-refresh script gen so PW
    # + Newman tests survive their own agent_token TTL during long
    # smokes (the Iter 11 evidence: ~110-140 min wallclock vs ~60 min
    # TTL → ~323 Newman 401 cluster fraction).

    @staticmethod
    def _r156_i_2_apply_refresh_flow(
        base_chains: dict[str, dict],
        refresh_flows: list[dict],
        target_kind: str = "agent_token",
        refresh_threshold_seconds: int = 60,
    ) -> dict[str, dict]:
        """R156.I.2 — return a NEW token-chains map with the canonical
        refresh_flow attached to the `target_kind` entry.

        Args:
            base_chains: base map (e.g., `_R156_B_1_TOKEN_CHAINS`).
            refresh_flows: list of refresh-flow dicts from R156.I.1
                (`endpoint_path`, `method`, `request_body_field`,
                `response_access_token_field`,
                `response_refresh_token_field`,
                `response_expires_in_field`).
            target_kind: which token chain to attach the refresh_flow to
                (default `agent_token` — the canonical seed target).
            refresh_threshold_seconds: TTL threshold below which the
                auto-refresh script should mint a fresh token (default 60).

        Returns:
            New map (shallow-copied at the top + at the target entry)
            with `<target_kind>.refresh_flow` populated when at least
            one refresh_flow detected. When `refresh_flows=[]` OR
            `target_kind` not in base, returns a shallow copy of base
            unchanged.

        Selection: when multiple refresh_flows detected, pick the FIRST
        one (R156.I.1 returns in file-iteration order; the canonical
        refresh endpoint typically sits in the auth module + is detected
        first). Future enhancement: scope-aware selection per project.
        """
        # Always return a fresh shallow copy so callers don't mutate
        # the class-level constant by accident.
        out: dict[str, dict] = {k: dict(v) for k, v in (base_chains or {}).items()}
        if not refresh_flows or target_kind not in out:
            return out
        first = refresh_flows[0]
        if not isinstance(first, dict):
            return out
        # Build canonical refresh_flow sub-dict consumed by R156.J helpers
        method = (first.get("method") or "POST").upper()
        endpoint_path = first.get("endpoint_path") or ""
        endpoint = f"{method} {endpoint_path}" if endpoint_path else ""
        body_field = first.get("request_body_field") or "refresh_token"
        access_field = first.get("response_access_token_field") or "access_token"
        # Both of these may be None when the SUT doesn't expose them
        refresh_field = first.get("response_refresh_token_field")
        expires_in_field = first.get("response_expires_in_field")
        out[target_kind]["refresh_flow"] = {
            "endpoint": endpoint,
            "request_body": {body_field: "<REFRESH_TOKEN_env>"},
            "response_access_field": access_field,
            "response_refresh_field": refresh_field,
            "expires_in_field": expires_in_field,
            "refresh_threshold_seconds": refresh_threshold_seconds,
        }
        return out

    # ── R156.B.2 — Per-endpoint token requirement classifier ──────────
    #
    # For each backend route already decorated by R156.A.2 with an
    # auth_requirement, walk R156.B.1's TOKEN_CHAINS to resolve the
    # FULL transitive chain of tokens the dispatched test must mint
    # before invoking the action. Stamps each route with:
    #   - token_chain:     [{kind, from, via, ttl_min}, ...] (full hops)
    #
    # Mission contract (Pillar 2 — execute flawlessly): R156.B.4 reads
    # these fields to render explicit setup→action chains in the LLM
    # prompt ("to call POST /api/v1/datasets, first mint agent_token via
    # so generated tests carry the right credential at dispatch time.
    # Combined with R98.2's domain-prefix backstop, the per-endpoint
    # classification supersedes the prefix heuristic with source-truth.

    @staticmethod
    def _r156_b_2_classify_endpoint_tokens(
        be_routes: list[dict],
        token_chains: dict[str, dict] | None = None,
    ) -> list[dict]:
        """R156.B.2 — for each BE route with an `auth_requirement` set
        by R156.A.2, attach `required_tokens` (ordered list of token
        kinds the test must mint) and `token_chain` (the full chain of
        hop dicts from R156.B.1).

        Args:
            be_routes: list of backend route dicts (typically the output
                of `_r104_b_extract_backend_routes_rest`, post-A.2).
            token_chains: chains map to resolve against. Defaults to the
                class-level `_R156_B_1_TOKEN_CHAINS`. Operator can pass
                an `_r156_i_2_apply_refresh_flow`-enriched map to get
                refresh_flow propagated through to the chain too.

        Returns:
            The SAME list of route dicts, mutated in place. Routes
            without an auth_requirement (or with token_kind="none") are
            left unchanged. Routes whose token_kind doesn't resolve in
            the chains map get an empty required_tokens list so the
            caller can fall back to R98.2 prefix routing.
        """
        if not be_routes:
            return be_routes
        chains = token_chains if token_chains is not None else \
            AutomationEngineerAgent._R156_B_1_TOKEN_CHAINS
        for route in be_routes:
            if not isinstance(route, dict):
                continue
            auth = route.get("auth_requirement")
            if not isinstance(auth, dict):
                continue
            token_kind = auth.get("token_kind") or ""
            if not token_kind or token_kind == "none":
                continue
            # Resolve the full chain via R156.B.1 — pass a temporary
            # static-method binding so a custom chains map can be used.
            # The class-level method always reads the class constant, so
            # we re-implement the walk inline here when a custom map is
            # supplied. To keep the helper composable, define a small
            # local resolver:
            def _resolve(target: str) -> list[dict]:
                if target not in chains:
                    return []
                hops_reverse: list[dict] = []
                cursor = target
                seen: set[str] = set()
                for _ in range(5):
                    if cursor in seen:
                        break
                    seen.add(cursor)
                    entry = chains.get(cursor) or {}
                    hop = {"kind": cursor}
                    for k, v in entry.items():
                        hop[k] = v
                    hops_reverse.append(hop)
                    upstream = entry.get("from")
                    if not upstream:
                        break
                    cursor = upstream
                return list(reversed(hops_reverse))

            chain = _resolve(token_kind)
            if chain:
                route["required_tokens"] = [h["kind"] for h in chain]
                route["token_chain"] = chain
            else:
                # Unknown token_kind — caller falls back to R98.2 prefix routing.
                route["required_tokens"] = []
                route["token_chain"] = []
        return be_routes

    # ── R156.B.3 — FK data dependency resolver ────────────────────────
    #
    # For each BE route with a body_schema_source (R156.A.1), parse for
    # foreign-key-shaped fields (`<entity>_id` / `<entity>Id`) and find
    # producer endpoints in the same be_routes list (`GET .../entities`,
    # `GET .../entities/me`). Stamps each route with a `data_dependencies`
    # list of `{field, producer_method, producer_path}` dicts so R156.B.4
    # can render explicit setup → action chains in the LLM prompt:
    #   "Before POST /api/v1/datasets, GET /api/v1/users/me to obtain
    #    owner_id; pass it as body.owner_id."
    #
    # Mission contract (Pillar 1): closes the body-field "FK invented out
    # of thin air" class — Iter 11 evidence: ~30-50 of the 171 Newman 400
    # cluster were owner_id / org_id / dataset_id references the LLM
    # hallucinated as constant strings instead of fetched dynamically.

    @staticmethod
    def _r156_b_3_resolve_data_dependencies(be_routes: list[dict]) -> list[dict]:
        """R156.B.3 — for each BE route with a body_schema_source, find
        FK fields + their producer endpoints in the same list. Mutates
        and returns the SAME list (`data_dependencies: list[dict]`
        attached when at least one FK has a resolvable producer).

        Heuristic FK extraction: `<word>_id:` or `<word>Id:` lines in
        the Pydantic / TS interface snippet. Skipped helper-id fields
        (`id`, `uuid`) which are typically auto-generated by the SUT.

        Producer resolution order per FK:
          1. `GET /<entity>s/me`  — common identity endpoint (e.g.,
             `users/me`, `organizations/me`)
          2. `GET /<entity>/me`   — singular variant
          3. `GET /<entity>s`     — plural list endpoint
          4. `GET /<entity>`      — singular endpoint
        First match wins. When no producer is found, the FK is omitted
        (LLM is left without the hint — caller may fall back to common
        test-data fixtures).
        """
        if not be_routes:
            return be_routes
        import re as _re_r156_b3

        # FK field regex — matches `<entity>_id:` or `<entity>Id:` in
        # Pydantic class snippets. Word boundary on left to avoid
        # `inside_id` matching `inside`. Excludes lone `id` (no entity).
        fk_field_re = _re_r156_b3.compile(
            r"^\s*(\w+?)_id\s*:|^\s*(\w+?)Id\s*:",
            _re_r156_b3.MULTILINE,
        )
        # FK fields that are typically NOT data dependencies (auto-set
        # by SUT, internal, or identifier that the test wouldn't need
        # to fetch via another endpoint).
        _R156_B_3_FK_FIELD_SKIP = {
            "id", "uuid", "pk", "primary",
        }

        # Index be_routes by normalized path for fast producer lookup.
        # Reuse R156.A.3's path normalizer so wildcards collapse the
        # same way.
        def _norm(p: str) -> str:
            return AutomationEngineerAgent._r156_a_3_normalize_path_for_match(p)

        # Build: lookup of {GET path → route entry} for producer search
        get_routes_by_path: dict[str, dict] = {}
        for r in be_routes:
            if not isinstance(r, dict):
                continue
            method = (r.get("method") or "").upper()
            if method != "GET":
                continue
            n = _norm(r.get("path") or "")
            if n:
                get_routes_by_path[n] = r

        # Semantic aliases: `owner_id` field producer is `users/me`,
        # `org_id` → `orgs/me` OR `organizations/me`, etc. Each entry
        # maps a field-prefix entity name to candidate producer
        # entity names. The helper tries all aliases + the original.
        _R156_B_3_ENTITY_ALIASES = {
            "owner": ["user", "users"],
            "creator": ["user", "users"],
            "author": ["user", "users"],
            "org": ["organization", "organizations", "orgs"],
            "tenant": ["organization", "tenant", "tenants"],
            "account": ["accounts", "subscriber"],
            "workspace": ["workspaces"],
            "project": ["projects"],
        }

        def _find_producer(entity: str) -> tuple[str, str] | None:
            """Look for a GET route that produces this entity. Tries
            (entity_plural)/me → (entity)/me → entity_plural → entity,
            with semantic aliases (e.g., `owner_id` → looks for
            `users/me`). Returns (method, canonical_path) or None.
            """
            if not entity:
                return None
            # Collect entity-name candidates: the original + aliases
            entity_names: list[str] = [entity]
            for alias in _R156_B_3_ENTITY_ALIASES.get(entity, []):
                if alias not in entity_names:
                    entity_names.append(alias)
            # Generate path candidates for each entity name
            candidates: list[str] = []
            for name in entity_names:
                plural = name if name.endswith("s") else name + "s"
                for shape in (
                    f"/{plural}/me", f"/{name}/me",
                    f"/{plural}", f"/{name}",
                ):
                    if shape not in candidates:
                        candidates.append(shape)

            # Look for any GET route whose normalized path ENDS with one
            # of the candidate shapes (handles `/api/v1/...` prefixes).
            for norm_path, route in get_routes_by_path.items():
                for cand in candidates:
                    if norm_path.endswith(cand):
                        return ("GET", route.get("path") or norm_path)
            return None

        for route in be_routes:
            if not isinstance(route, dict):
                continue
            body_src = route.get("body_schema_source")
            if not body_src:
                continue
            # Find FK field names in the schema
            fks: list[str] = []
            seen_fks: set[str] = set()
            for m in fk_field_re.finditer(body_src):
                entity = (m.group(1) or m.group(2) or "").strip()
                if not entity:
                    continue
                if entity.lower() in _R156_B_3_FK_FIELD_SKIP:
                    continue
                # Field name format: `<entity>_id` for snake; we preserve
                # the SOURCE field as the dependency key so the LLM gets
                # the exact body field name (snake vs camel matters).
                # Reconstruct: if regex matched the snake variant
                # (m.group(1)), field = `<entity>_id`; otherwise camel
                # (m.group(2)) → `<entity>Id`.
                if m.group(1):
                    field_name = f"{entity}_id"
                else:
                    field_name = f"{entity}Id"
                if field_name in seen_fks:
                    continue
                seen_fks.add(field_name)
                fks.append((field_name, entity))  # type: ignore[arg-type]

            if not fks:
                continue
            # For each FK, look for a producer
            data_deps: list[dict] = []
            for field_name, entity in fks:  # type: ignore[misc]
                # Skip self-referential FK if it points back to this route
                producer = _find_producer(entity.lower())
                if not producer:
                    continue
                producer_method, producer_path = producer
                # Don't recommend producing the entity via the same
                # route being decorated (rare, but possible if the SUT
                # has `POST /datasets` returning a dataset whose body
                # ALSO requires a dataset_id — which would be circular).
                if (producer_path == route.get("path")
                        and producer_method == route.get("method", "").upper()):
                    continue
                data_deps.append({
                    "field": field_name,
                    "producer_method": producer_method,
                    "producer_path": producer_path,
                })
            if data_deps:
                route["data_dependencies"] = data_deps
        return be_routes

    # ── R156.B.4 — Auth-graph + data-dependency prompt block ─────────
    #
    # Renders the accumulated R156.A.1 (body schema) + R156.A.2 (auth
    # requirement) + R156.B.2 (required tokens) + R156.B.3 (data
    # dependencies) + R156.I.2 (refresh flow) metadata into a compact
    # HARD CONSTRAINT block that's appended to both PW and Newman
    # generation prompts. The LLM sees per-endpoint:
    #   - which token kind to send
    #   - the request body schema (field names + types)
    #   - any FK setup requests required first
    # + a consolidated token-chain summary so it understands the
    #
    # Mission contract: closes both the body-field hallucination class
    # AND the wrong-token-at-dispatch class — the LLM now has the
    # explicit per-endpoint contract sourced from real SUT code.

    @staticmethod
    def _r156_b_4_render_auth_graph_block(
        be_routes: list[dict],
        token_chains: dict[str, dict] | None = None,
    ) -> str:
        """R156.B.4 — render the per-endpoint auth/body/data-dep block
        + token-chain summary. Returns the formatted prompt string,
        or empty string when no routes carry any source-derived
        metadata (i.e., R156.A.1/A.2/A.3 returned nothing — fall back
        to existing R98.3 captured_endpoints grounding).
        """
        if not be_routes:
            return ""
        # Collect routes that have at least one source-derived field.
        # Routes with no auth_requirement, no body_schema, no data deps
        # are skipped here (they appear in the plain BACKEND ROUTES
        # list above this block but don't need explicit token guidance).
        authed_routes = [
            r for r in be_routes
            if isinstance(r, dict) and (
                r.get("auth_requirement") or r.get("body_schema_source")
                or r.get("data_dependencies") or r.get("required_tokens")
            )
        ]
        if not authed_routes:
            return ""
        chains = token_chains if token_chains is not None else \
            AutomationEngineerAgent._R156_B_1_TOKEN_CHAINS

        lines: list[str] = [
            "",
            "[R156.B AUTH GRAPH + DATA DEPENDENCIES (from SUT source)]",
            "For each endpoint your test invokes, use the token kind + body schema below:",
        ]

        # Track which token kinds are actually referenced — used to
        # render only the relevant chain hops in the summary table.
        referenced_kinds: set[str] = set()

        for r in authed_routes[:25]:
            method = (r.get("method") or "GET").upper()
            path = r.get("path") or ""
            auth = r.get("auth_requirement") or {}
            token_kind = auth.get("token_kind") or "none"
            scopes = auth.get("scopes") or []
            scope_suffix = f" scopes={list(scopes)}" if scopes else ""
            lines.append(f"  - {method} {path} requires {{{token_kind}}}{scope_suffix}")
            if token_kind and token_kind != "none":
                referenced_kinds.add(token_kind)

            # Body schema (compact: just the class header + first ~8 fields)
            body = r.get("body_schema_source")
            if body:
                body_snippet_lines = body.split("\n")[:9]
                lines.append("      body_schema:")
                for sl in body_snippet_lines:
                    lines.append(f"        {sl}")
                if len(body.split("\n")) > 9:
                    lines.append("        # (truncated)")

            # Data dependencies (FK setup → action chain)
            deps = r.get("data_dependencies") or []
            for dep in deps[:5]:
                dep_field = dep.get("field") or ""
                dep_method = (dep.get("producer_method") or "GET").upper()
                dep_path = dep.get("producer_path") or ""
                lines.append(
                    f"      data_dependency: `{dep_field}` MUST be fetched first "
                    f"via {dep_method} {dep_path}",
                )

        # Token-chain summary — only render hops for kinds that actually
        # appear above. This keeps the prompt budget tight for projects
        # that only use one or two token kinds.
        if referenced_kinds:
            # Resolve the union of required hops by walking each referenced
            # kind back to root and accumulating unique entries.
            all_hops: list[dict] = []
            seen_kinds_in_chain: set[str] = set()
            for kind in referenced_kinds:
                # Inline mini-resolver (mirrors B.2 / B.1 logic) so we can
                # accept the optionally-enriched token_chains map.
                cursor = kind
                local_seen: set[str] = set()
                for _ in range(5):
                    if cursor in local_seen:
                        break
                    local_seen.add(cursor)
                    entry = chains.get(cursor) or {}
                    if cursor not in seen_kinds_in_chain:
                        seen_kinds_in_chain.add(cursor)
                        hop = {"kind": cursor}
                        for k, v in entry.items():
                            hop[k] = v
                        all_hops.append(hop)
                    upstream = entry.get("from")
                    if not upstream:
                        break
                    cursor = upstream
            # expands outward. We render the chain by walking from root.
            # Use a simple insertion-order approach: render in topological
            # order by walking the chain map.
            lines.append("")
            lines.append(
                "Token chain (dispatcher populates AUTH_TOKEN env with the right token):"
            )
            roots: list[str] = [
                k for k, v in chains.items()
                if not v.get("from") and k in seen_kinds_in_chain
            ]
            # directly referenced (since downstream kinds derive from it).
            if "session_token" in chains and "session_token" not in roots and \
                    seen_kinds_in_chain:
                roots.insert(0, "session_token")
            rendered: set[str] = set()
            for root in roots:
                if root in rendered:
                    continue
                rendered.add(root)
                root_src = (chains.get(root) or {}).get("source") or ""
                src_suffix = f" ({root_src})" if root_src else ""
                lines.append(f"  {root}{src_suffix}")
            # Then render each downstream kind referenced
            # in order of chain depth.
            depth_ordered = [
                k for k in seen_kinds_in_chain
                if k not in rendered
            ]
            depth_ordered.sort(key=lambda k: len(
                AutomationEngineerAgent._r156_b_1_resolve_token_chain(k)
                if k in AutomationEngineerAgent._R156_B_1_TOKEN_CHAINS else [k]
            ))
            for kind in depth_ordered:
                entry = chains.get(kind) or {}
                upstream = entry.get("from") or "?"
                via = entry.get("via") or ""
                ttl = entry.get("ttl_min")
                ttl_suffix = f" (TTL {ttl}min)" if ttl else ""
                lines.append(
                    f"  {upstream} → {kind}{ttl_suffix}"
                    + (f" via {via}" if via else "")
                )
                rendered.add(kind)
                # If this kind has a refresh_flow attached (R156.I.2),
                # surface the refresh contract so the auto-refresh
                # scripts the LLM emits know which fields to use.
                rf = entry.get("refresh_flow")
                if rf:
                    rf_endpoint = rf.get("endpoint") or ""
                    rf_body = rf.get("request_body") or {}
                    rf_access = rf.get("response_access_field") or ""
                    rf_refresh = rf.get("response_refresh_field")
                    rf_expires = rf.get("expires_in_field")
                    rf_thresh = rf.get("refresh_threshold_seconds") or 60
                    lines.append(
                        f"    refresh_flow: {rf_endpoint}"
                        f"  body={dict(rf_body)}"
                        f"  →  access:{rf_access}"
                        + (f", refresh:{rf_refresh}" if rf_refresh else "")
                        + (f", expires_in:{rf_expires}" if rf_expires else "")
                        + f"  (refresh when TTL<{rf_thresh}s)"
                    )

        lines.append("")
        lines.append("HARD CONSTRAINT (R156.B):")
        lines.append(
            "  - Use ONLY field names + types from body_schema above; "
            "do NOT invent fields."
        )
        lines.append(
            "  - For each endpoint, use the token kind specified in "
            "`requires {...}`."
        )
        lines.append(
            "  - When `data_dependency` is shown, emit the producer "
            "request FIRST + use its response value in the body."
        )
        lines.append(
            "  - When a token kind needs minting from an upstream kind, "
            "emit the chain hop request before the action."
        )
        lines.append("[END R156.B AUTH GRAPH]")
        return "\n".join(lines)

    # ── R156.C — Multi-protocol detection + audit + handoff routing ──
    #
    # R156.C.1: per-route classifier — tags each backend route with one
    # of `rest` / `grpc` / `sse` / `websocket` / `graphql` based on
    # decorator + handler-body signals (and file-level gRPC server
    # markers). Default is `rest`.
    #
    # R156.C.2: per-batch aggregator — counts each protocol across the
    # accumulated be_routes list + flags analytics-domain endpoints
    # using non-REST protocols (operator typically cares about these
    # for the Pillar 4 dashboard).
    #
    # R156.C.3: handoff routing — stamps each non-REST endpoint with a
    # `gen_handoff` field naming the gen pipeline that should produce
    # the test (`grpc_pytest` for R156.E, `sse_pw` for R156.G,
    # `websocket_pw` for R156.H). Default `gen_handoff` is `rest_default`.
    #
    # Mission contract (Pillar 4 — truthful SUT reporting): silent
    # `test.skip(non-REST endpoint)` outputs hide real SUT capability
    # gaps. R156.C makes the gap operator-visible + routes specs to
    # the right generator so non-REST tests actually exercise the SUT.

    _R156_C_SSE_HEADER_RE_SRC = (
        r"(?:text/event-stream|EventSourceResponse\s*\(|"
        r"setHeader\(\s*['\"]Content-Type['\"]\s*,\s*['\"]text/event-stream)"
    )
    _R156_C_WEBSOCKET_DECORATOR_RE_SRC = (
        r"@(?:app|router)\.websocket\s*\("
    )
    _R156_C_WEBSOCKET_BODY_RE_SRC = (
        r"\bws\.on\(|\bsocket\.on\(|\bsocketio\.|\bSocketIO\("
    )
    _R156_C_GRPC_FILE_RE_SRC = (
        r"\bimport\s+grpc\b|\bgrpc\.aio\.server\(|"
        r"\badd_\w+Servicer_to_server\b|\b_pb2_grpc\b"
    )
    _R156_C_GRAPHQL_FILE_RE_SRC = (
        r"\bstrawberry\.field\b|\bapollo-server\b|"
        r"\bgql\s*`|\bbuildSchema\s*\("
    )
    # C1 mirror (2026-07-25) — file-level SOAP + .NET SignalR indicators so the precise
    # source classifier matches the heuristic _classify_protocol additions.
    _R156_C_SOAP_FILE_RE_SRC = (
        r"\[SoapDocumentMethod\b|\[WebMethod\b|\bSoapCore\b|"
        r"\bSystem\.Web\.Services\b|\bimport\s+spyne\b|soap[:.]envelope"
    )
    _R156_C_SIGNALR_FILE_RE_SRC = (
        r"Microsoft\.AspNetCore\.SignalR|\bIHubContext\b|\.MapHub\s*<|"
        r"\[HubMethodName\b|\bClients\.(?:All|Caller|Group)\b"
    )

    _R156_C_HANDOFF_FOR_PROTOCOL = {
        "rest":      "rest_default",
        "grpc":      "grpc_pytest",    # R156.E gen pipeline
        "sse":       "sse_pw",         # R156.G gen pipeline
        "websocket": "websocket_pw",   # R156.H gen pipeline
        "graphql":   "graphql_deferred",  # not in scope this phase
    }

    @staticmethod
    def _r156_c_1_classify_route_protocol(
        file_content: str,
        route_match_start: int,
        route_match_end: int,
    ) -> str:
        """R156.C.1 — return one of `rest|grpc|sse|websocket|graphql`
        based on the route match + handler body + file-level signals.

        Priority order:
          1. Decorator literal: `@app.websocket(` or `@router.websocket(`
             → `websocket` (Python ASGI convention).
          2. SSE response signature in the handler body (next ~80 lines):
             `EventSourceResponse(...)`, `text/event-stream` mime,
             `res.setHeader('Content-Type', 'text/event-stream')`.
          3. WebSocket handler-body markers: `ws.on(`, `socket.on(`.
          4. File-level gRPC indicators (whole file): if the route
             appears in a file that ALSO sets up gRPC servicers, classify
             as `grpc`.
          5. File-level GraphQL indicators.
          6. Default `rest`.
        """
        import re as _re_r156_c1
        # 1) Decorator literal check (look at the match start - 50 chars)
        decorator_window = file_content[max(0, route_match_start - 50):route_match_end]
        if _re_r156_c1.search(
            AutomationEngineerAgent._R156_C_WEBSOCKET_DECORATOR_RE_SRC,
            decorator_window,
        ):
            return "websocket"

        # 2) Handler-body window (next 80 lines after the route match)
        handler_window = file_content[route_match_end:route_match_end + 4000]
        if _re_r156_c1.search(
            AutomationEngineerAgent._R156_C_SSE_HEADER_RE_SRC,
            handler_window,
        ):
            return "sse"

        # 3) WebSocket-body markers (Express / socket.io)
        if _re_r156_c1.search(
            AutomationEngineerAgent._R156_C_WEBSOCKET_BODY_RE_SRC,
            handler_window,
        ):
            return "websocket"

        # 3.5) File-level SOAP / .NET SignalR (C1 mirror)
        if _re_r156_c1.search(
            AutomationEngineerAgent._R156_C_SOAP_FILE_RE_SRC, file_content,
        ):
            return "soap"
        if _re_r156_c1.search(
            AutomationEngineerAgent._R156_C_SIGNALR_FILE_RE_SRC, file_content,
        ):
            return "signalr"

        # 4) File-level gRPC indicators
        if _re_r156_c1.search(
            AutomationEngineerAgent._R156_C_GRPC_FILE_RE_SRC,
            file_content,
        ):
            return "grpc"

        # 5) File-level GraphQL indicators
        if _re_r156_c1.search(
            AutomationEngineerAgent._R156_C_GRAPHQL_FILE_RE_SRC,
            file_content,
        ):
            return "graphql"

        return "rest"

    @staticmethod
    def _r156_c_3_assign_gen_handoff(protocol: str) -> str:
        """R156.C.3 — map protocol → gen pipeline name. Reads the
        `_R156_C_HANDOFF_FOR_PROTOCOL` table for the canonical mapping;
        defaults to `rest_default` when the protocol is unknown."""
        return AutomationEngineerAgent._R156_C_HANDOFF_FOR_PROTOCOL.get(
            protocol or "rest", "rest_default",
        )

    @staticmethod
    def _r156_c_classify_routes_inplace(
        be_routes: list[dict],
        file_content_by_path: dict[str, str] | None = None,
    ) -> list[dict]:
        """R156.C convenience wrapper: when called WITHOUT
        `file_content_by_path`, leaves routes' `protocol` field alone
        (R156.A.1 handler runs per-file during MCP extraction, so the
        per-route classification happens inline there).

        When the caller has access to the cached file_content per route
        path, this helper can re-classify after the fact. R156.C.2
        aggregation runs over the result regardless.

        Routes without `protocol` field default to `rest` after this
        call. `gen_handoff` is always populated.
        """
        if not be_routes:
            return be_routes
        for route in be_routes:
            if not isinstance(route, dict):
                continue
            # Honor a pre-existing `protocol` field (set inline during
            # source-walk) — only default when missing.
            if "protocol" not in route:
                route["protocol"] = "rest"
            route["gen_handoff"] = AutomationEngineerAgent._r156_c_3_assign_gen_handoff(
                route.get("protocol") or "rest",
            )
        return be_routes

    @staticmethod
    def _r156_c_2_audit_protocol_coverage(be_routes: list[dict]) -> dict:
        """R156.C.2 — aggregate per-protocol counts + flag analytics-
        domain endpoints using non-REST protocols.

        Returns:
            {
              "counts": {"rest": N, "grpc": M, "sse": K, ...},
              "non_rest_analytics_routes": [
                {"method": ..., "path": ..., "protocol": ...}, ...
              ],
            }
        """
        counts: dict[str, int] = {}
        non_rest_analytics: list[dict] = []
        _ANALYTICS_KEYWORDS = (
            "insight", "analytics", "stream", "chat",
            "metric", "report", "dashboard",
        )
        for route in be_routes or []:
            if not isinstance(route, dict):
                continue
            proto = (route.get("protocol") or "rest").lower()
            counts[proto] = counts.get(proto, 0) + 1
            if proto != "rest":
                path_lower = (route.get("path") or "").lower()
                if any(kw in path_lower for kw in _ANALYTICS_KEYWORDS):
                    non_rest_analytics.append({
                        "method": route.get("method"),
                        "path": route.get("path"),
                        "protocol": proto,
                    })
        return {
            "counts": counts,
            "non_rest_analytics_routes": non_rest_analytics,
        }

    # ── R156.F — .proto IDL parse (regex-based; no protoc) ───────────────
    #
    # R156.F is the cross-tool sibling of R156.A.1 (Pydantic body
    # schema). When R156.A's source-walk discovers `.proto` files, this
    # helper extracts message + field + service + rpc metadata WITHOUT
    # invoking protoc as a subprocess. Pure regex/Python — fully unit-
    # testable + works in cold-start environments where the SUT's proto
    # ecosystem isn't installed in ARTA's container.
    #
    # Stub generation (the `*_pb2.py` / `*_pb2_grpc.py` output of protoc)
    # is INTENTIONALLY out of R156.F's MVP — operators ship those stubs
    # in their pytest runtime image OR install grpcio-tools and run
    # protoc themselves. A future R-phase can layer subprocess invocation
    # on top of R156.F's existing detection.
    #
    # Composes with:
    #   - R156.A.1 body_schema (Pydantic/Joi/Zod) — both populate the
    #     same `body_schema` field on routes; gRPC routes carry the
    #     proto-derived shape
    #   - R156.B.4 prompt block — when route.body_schema_source comes
    #     from a .proto, the prompt teaches gRPC field types alongside
    #     REST body schemas
    #   - R156.C protocol detection — .proto files SET protocol="grpc"
    #   - R156.E GrpcClient — generated pytest tests assert on the
    #     fields extracted by R156.F

    _R156_F_PROTO_MESSAGE_PATTERN = r"""
        ^\s*message\s+(?P<name>\w+)\s*\{      # `message Name {`
        (?P<body>(?:[^{}]|\{[^{}]*\})*)       # body (non-nested or 1-level nested)
        \}
    """

    _R156_F_PROTO_FIELD_PATTERN = r"""
        ^\s*
        (?P<rule>repeated|optional|required)?\s*
        (?P<type>\w+(?:\.\w+)*)\s+             # field type (e.g., string, int32, MyMessage)
        (?P<name>\w+)\s*=\s*(?P<tag>\d+)       # field name + tag number
        (?:\s*\[[^\]]*\])?\s*;                 # optional field options [deprecated = true]
    """

    _R156_F_PROTO_SERVICE_PATTERN = r"""
        ^\s*service\s+(?P<name>\w+)\s*\{       # `service Name {`
        (?P<body>(?:[^{}]|\{[^{}]*\})*)        # body
        \}
    """

    _R156_F_PROTO_RPC_PATTERN = r"""
        ^\s*rpc\s+(?P<name>\w+)\s*             # `rpc Method`
        \(\s*(?P<req_stream>stream\s+)?
           (?P<req_type>\w+(?:\.\w+)*)\s*\)    # `(stream? RequestType)`
        \s*returns\s*
        \(\s*(?P<resp_stream>stream\s+)?
           (?P<resp_type>\w+(?:\.\w+)*)\s*\)   # `returns (stream? ResponseType)`
        (?:\s*\{[^}]*\})?\s*;?                 # optional options block + trailing ;
    """

    @staticmethod
    def _r156_f_parse_proto_messages(proto_content: str) -> list[dict]:
        """R156.F — extract message types + fields from .proto source.

        Returns a list of dicts shaped:
          [{
            "name": "DatasetCreate",
            "fields": [
              {"name": "name", "type": "string", "tag": 1, "rule": None},
              {"name": "owner_id", "type": "string", "tag": 2, "rule": None},
              {"name": "tags", "type": "string", "tag": 3, "rule": "repeated"},
            ],
          }, ...]

        Comment lines (`// foo` / `/* foo */`) are stripped before
        parsing. Nested messages 1-level deep are tolerated; >1-level
        nesting falls back to the outer message only (R156.F's regex
        is pragmatic, not protoc-grade).
        """
        if not proto_content or not isinstance(proto_content, str):
            return []
        import re as _re_r156f
        # Strip line comments + block comments to avoid false-positive
        # `field;` patterns inside commented-out fields.
        cleaned = _re_r156f.sub(r"//[^\n]*", "", proto_content)
        cleaned = _re_r156f.sub(r"/\*.*?\*/", "", cleaned, flags=_re_r156f.DOTALL)
        out: list[dict] = []
        msg_re = _re_r156f.compile(
            AutomationEngineerAgent._R156_F_PROTO_MESSAGE_PATTERN,
            _re_r156f.MULTILINE | _re_r156f.VERBOSE,
        )
        field_re = _re_r156f.compile(
            AutomationEngineerAgent._R156_F_PROTO_FIELD_PATTERN,
            _re_r156f.MULTILINE | _re_r156f.VERBOSE,
        )
        for m_match in msg_re.finditer(cleaned):
            msg_name = m_match.group("name")
            body = m_match.group("body") or ""
            fields: list[dict] = []
            for f_match in field_re.finditer(body):
                # Skip non-field lines (oneof bodies, reserved, etc.)
                f_type = f_match.group("type")
                if f_type in ("oneof", "reserved", "extensions", "option"):
                    continue
                try:
                    tag_int = int(f_match.group("tag"))
                except (ValueError, TypeError):
                    continue
                fields.append({
                    "name": f_match.group("name"),
                    "type": f_type,
                    "tag": tag_int,
                    "rule": f_match.group("rule"),  # repeated|optional|required|None
                })
            out.append({"name": msg_name, "fields": fields})
        return out

    @staticmethod
    def _r156_f_parse_proto_services(proto_content: str) -> list[dict]:
        """R156.F — extract service + rpc method declarations from
        .proto source.

        Returns a list of dicts shaped:
          [{
            "name": "AuthService",
            "rpcs": [
              {
                "name": "VerifyToken",
                "request_type": "VerifyTokenRequest",
                "response_type": "VerifyTokenResponse",
                "request_streaming": False,
                "response_streaming": False,
              },
              {
                "name": "StreamInsights",
                "request_type": "StreamRequest",
                "response_type": "InsightChunk",
                "request_streaming": False,
                "response_streaming": True,
              },
            ],
          }, ...]
        """
        if not proto_content or not isinstance(proto_content, str):
            return []
        import re as _re_r156f
        cleaned = _re_r156f.sub(r"//[^\n]*", "", proto_content)
        cleaned = _re_r156f.sub(r"/\*.*?\*/", "", cleaned, flags=_re_r156f.DOTALL)
        out: list[dict] = []
        svc_re = _re_r156f.compile(
            AutomationEngineerAgent._R156_F_PROTO_SERVICE_PATTERN,
            _re_r156f.MULTILINE | _re_r156f.VERBOSE,
        )
        rpc_re = _re_r156f.compile(
            AutomationEngineerAgent._R156_F_PROTO_RPC_PATTERN,
            _re_r156f.MULTILINE | _re_r156f.VERBOSE,
        )
        for s_match in svc_re.finditer(cleaned):
            svc_name = s_match.group("name")
            body = s_match.group("body") or ""
            rpcs: list[dict] = []
            for r_match in rpc_re.finditer(body):
                rpcs.append({
                    "name": r_match.group("name"),
                    "request_type": r_match.group("req_type"),
                    "response_type": r_match.group("resp_type"),
                    "request_streaming": bool(r_match.group("req_stream")),
                    "response_streaming": bool(r_match.group("resp_stream")),
                })
            out.append({"name": svc_name, "rpcs": rpcs})
        return out

    @staticmethod
    def _r156_f_extract_proto_schemas(proto_content: str) -> dict:
        """R156.F — orchestrator: extract both message + service
        catalogs from a .proto file's content. Returns:

          {
            "messages": [...],   # R156.F._r156_f_parse_proto_messages output
            "services": [...],   # R156.F._r156_f_parse_proto_services output
            "package": "auth.v1" if `package` declaration present else None,
            "syntax": "proto3" | "proto2" | None,
          }

        Empty input → empty result dict with messages=[], services=[].
        """
        if not proto_content or not isinstance(proto_content, str):
            return {"messages": [], "services": [], "package": None, "syntax": None}
        import re as _re_r156f
        # package declaration (e.g., `package auth.v1;`)
        package = None
        pkg_match = _re_r156f.search(
            r"^\s*package\s+([\w.]+)\s*;", proto_content, _re_r156f.MULTILINE,
        )
        if pkg_match:
            package = pkg_match.group(1)
        # syntax declaration (e.g., `syntax = "proto3";`)
        syntax = None
        syn_match = _re_r156f.search(
            r"""^\s*syntax\s*=\s*["'](proto[23])["']\s*;""",
            proto_content, _re_r156f.MULTILINE,
        )
        if syn_match:
            syntax = syn_match.group(1)
        return {
            "messages": AutomationEngineerAgent._r156_f_parse_proto_messages(
                proto_content,
            ),
            "services": AutomationEngineerAgent._r156_f_parse_proto_services(
                proto_content,
            ),
            "package": package,
            "syntax": syntax,
        }

    async def disconnect_mcp(self) -> None:
        """R104.B — cleanly close MCP connections owned by this agent."""
        for name, client in list(self._mcp_clients.items()):
            try:
                if hasattr(client, "stop"):
                    await client.stop()
            except Exception as exc:
                log.debug("R104.B: MCP %s disconnect error: %s", name, exc)
        self._mcp_clients.clear()
        self._mcp_connected = False

    # R248 — a requirement is a LOGIN/SSO flow when its text names UI-login /
    # identity-provider concepts. Such reqs cannot be UI-tested reliably: the login
    # page + external IdP (Auth0) are not in the DOM catalog (the probe runs
    # authenticated), so the LLM hallucinates the login button + guessed auth routes
    # (/Error, /callback) → every assertion times out. Steer them to API-first.
    _LOGIN_FLOW_RE = re.compile(
        r"(\blogin\b|log(?:s|ging|ged)?[\s-]?in|sign(?:s|ing|ed)?[\s-]?in|\bsso\b|"
        r"auth0|login[\s-]?callback|email[\s-]?login|handleauth0|"
        r"session\s+establish|identity\s+provider)", re.I)

    @staticmethod
    def _r248_login_flow_pw_constraint(gherkin_text: str) -> str:
        """R248 — for a LOGIN/SSO requirement, return a HARD CONSTRAINT steering PW
        gen to API-level auth testing (the grounded login endpoint) instead of the
        ungroundable login UI / external IdP. Empty for non-login reqs."""
        if not gherkin_text or not AutomationEngineerAgent._LOGIN_FLOW_RE.search(gherkin_text):
            return ""
        return (
            "\n\n[PLAYWRIGHT SCRIPT — LOGIN/SSO REQUIREMENT (API-FIRST)]\n"
            "This requirement concerns authentication / SSO. The login PAGE and any "
            "external identity provider (e.g. Auth0) are NOT in the DOM catalog and "
            "CANNOT be UI-tested reliably — a UI login-form/button interaction or an "
            "assertion on a guessed auth route TIMES OUT for an irrelevant reason.\n"
            "- Test authentication via the DISCOVERED login API endpoint from the "
            "grounded list (e.g. a `.../email-login` or `.../sso/api/login` route): "
            "`const r = await page.request.post('<that endpoint>', { data: {…} }); "
            "expect([200,400,401,403]).toContain(r.status());` and assert on the "
            "RESPONSE (status class + a field EXISTS), not on the UI.\n"
            "- Do NOT: fill or click a login form "
            "(getByRole('button',{name:/login|sign in|submit/}), email/password inputs); "
            "call page.waitForURL()/assert page.url() for a guessed route "
            "('/Error','/callback','/handleAuth0LoginCallback' redirects) that is NOT in "
            "the DOM catalog.\n"
            "- A NEGATIVE auth case asserts the API REJECTS it (status in [400,401,403]), "
            "NOT navigation to a specific error route.\n"
        )

    # R248.B — the hallucinated login-submit button (role=button + a
    # /submit|login|sign in/ name-regex). It isn't in the DOM catalog, so each
    # click TIMES OUT (~30s) and a few blow the spec's 600s budget → the whole
    # spec is killed before the good (API-first) tests can run.
    _LOGIN_BTN_RE = re.compile(
        r"getByRole\(\s*['\"]button['\"][^)]*?(submit|log\s?in|sign\s?in|\blogin\b)",
        re.I)

    @staticmethod
    def _r248_b_strip_login_ui(content: str) -> tuple[str, int]:
        """R248.B — deterministically SKIP PW `test(...)` blocks that interact with
        the hallucinated login UI (a login/submit button by role+name-regex not in
        the DOM catalog). Converts `test('…', …)` → `test.skip('…', …)` for those
        blocks: TRUTHFUL (the login UI is ungroundable; R248's API-first tests cover
        the requirement) and it stops the ~30s-per-click timeouts from starving the
        spec's time budget so the good tests actually run. Returns (content, count).
        Companion to the R248 prompt constraint (which the batch LLM only partially
        obeys). Killswitch handled by the caller."""
        if not content or "getByRole" not in content:
            return content, 0
        _btn = AutomationEngineerAgent._LOGIN_BTN_RE
        _inserts: list[int] = []
        for m in re.finditer(r"\btest(\.skip|\.only|\.fixme)?\s*\(", content):
            if m.group(1):          # already test.skip/.only/.fixme
                continue
            _arrow = content.find("=> {", m.end())
            if _arrow < 0 or (_arrow - m.end()) > 400:
                continue            # arrow not near → not a simple test block
            _depth, _j = 0, _arrow + 3
            _body_start = _j
            while _j < len(content):
                _c = content[_j]
                if _c == "{":
                    _depth += 1
                elif _c == "}":
                    _depth -= 1
                    if _depth == 0:
                        break
                _j += 1
            if _btn.search(content[_body_start:_j]):
                _inserts.append(m.start() + 4)   # right after 'test'
        if not _inserts:
            return content, 0
        for _pos in sorted(_inserts, reverse=True):
            content = content[:_pos] + ".skip" + content[_pos:]
        return content, len(_inserts)

    def _r195_workflow_pipeline_block(self, be_routes: list, gherkin_text: str) -> str:
        """R195 KEYSTONE — topologically order the data-dependency DAG into the
        SUT's ACTION workflow pipeline and emit it as ONE ordered, protocol-tagged
        sequence.

        Operator-confirmed pilot flow: create dataset (connect datasource) →
        configure app → create agent token → launch app — and the SUT spans
        SSE/REST/gRPC. R156.B.3 already extracts per-route FK data-dependencies
        (field → producer endpoint) and R156.C stamps `protocol`, but R156.B.4
        injects the deps as ISOLATED single-level hints ("dataset_id must be
        fetched first") — never the TRANSITIVE, topologically-ordered chain. So
        the LLM never sees "to launch an app you must FIRST create a dataset,
        THEN configure an app, THEN mint an agent token, IN THAT ORDER". This
        builds that ordered pipeline (transitive producer chain of the
        Gherkin-relevant target, producers first) and tags each step's protocol
        so the LLM uses the right client (REST request / SSE subscribe / gRPC →
        pytest). Auto-derived from code (data-deps) + the requirement
        (target selection) — no hardcoded flow. Killswitch
        ARTA_R195_WORKFLOW_PIPELINE_DISABLE=1."""
        import os as _os
        if _os.environ.get("ARTA_R195_WORKFLOW_PIPELINE_DISABLE") == "1":
            return ""
        if not be_routes:
            return ""

        def _norm(p: str) -> str:
            return "/" + "/".join(s for s in (p or "").split("/") if s)
        # Index routes by normalized path; collect each route's producer paths
        # (the routes that produce a field this route consumes).
        by_path: dict = {}
        for r in be_routes:
            if isinstance(r, dict) and r.get("path"):
                by_path.setdefault(_norm(r["path"]), r)
        if not by_path:
            return ""

        def _producers(route: dict) -> list:
            out = []
            for dep in (route.get("data_dependencies") or []):
                pp = _norm(dep.get("producer_path") or "")
                prod = by_path.get(pp)
                if prod is not None and prod is not route:
                    out.append((dep.get("field") or "", prod))
            return out
        # Target = the most Gherkin-relevant route that HAS dependencies (the
        # action under test, e.g. launch/create). Prefer mutating verbs +
        # relevance; require >=1 dependency so there's a real chain.
        _gl = (gherkin_text or "").lower().replace("-", "").replace("_", "")

        def _rel(r: dict) -> int:
            score = sum(1 for s in _norm(r.get("path", "")).split("/")
                        if s and s.replace("-", "").replace("_", "") in _gl)
            if (r.get("method") or "GET").upper() in ("POST", "PUT", "PATCH"):
                score += 1  # actions are the workflow endpoints
            return score
        cand = [r for r in be_routes
                if isinstance(r, dict) and (r.get("data_dependencies") or [])]
        if not cand:
            return ""
        cand.sort(key=lambda r: -_rel(r))
        target = cand[0]
        # Transitive producer chain via post-order DFS (producers emitted before
        # the consumer); cycle-safe via a visiting set.
        ordered: list = []
        seen: set = set()
        visiting: set = set()

        def _visit(route: dict, in_field: str = ""):
            key = (route.get("method"), _norm(route.get("path", "")))
            if key in seen or key in visiting:
                return
            visiting.add(key)
            for field, prod in _producers(route):
                _visit(prod, field)
            visiting.discard(key)
            seen.add(key)
            ordered.append((route, in_field))
        _visit(target)
        if len(ordered) < 2:
            return ""  # single endpoint, no multi-step pipeline
        _PROTO_CALL = {
            "rest": "page.request.<verb>(url) (REST)",
            "sse": "subscribeToEventStream(...) from ../common/sse_helpers (NOT page.request — it's a stream)",
            "websocket": "openAuthenticatedWebSocket(...) from ../common/websocket_helpers",
            "grpc": "(gRPC — assert via the pytest/grpc layer, not page.request)",
            "graphql": "page.request.post(graphql endpoint) with a query body",
        }
        lines = [
            "[HARD CONSTRAINT — WORKFLOW PIPELINE (data-dependency order; establish each step before the next)]",
            "This SUT action depends on upstream resources. Perform these steps IN "
            "THIS EXACT ORDER (each produces a value the next step consumes — "
            "capture it from the response and pass it forward). Do NOT call the "
            "final action without first establishing every preceding step:",
        ]
        for i, (r, in_field) in enumerate(ordered, 1):
            m = (r.get("method") or "GET").upper()
            p = _norm(r.get("path", ""))
            proto = (r.get("protocol") or "rest").lower()
            call = _PROTO_CALL.get(proto, _PROTO_CALL["rest"])
            provides = ", ".join(
                dep.get("field", "") for dep in (r.get("data_dependencies") or [])
            )
            role = "FINAL ACTION (the feature under test)" if r is target else "prerequisite"
            note = f" — consumed downstream as `{in_field}`" if in_field else ""
            lines.append(f"  {i}. [{proto}] {m} {p}  // {role}; call via {call}{note}")
            if provides and r is not target:
                lines.append(f"       capture from this step's response the id(s) the next step needs ({provides} are its own inputs)")
        lines.append(
            "Thread the real id from each step's response into the next step's "
            "URL/body (do NOT invent ids). For non-REST steps use the protocol "
            "helper shown, not page.request.")
        lines.append("[END HARD CONSTRAINT — WORKFLOW PIPELINE]")
        return "\n".join(lines)

    async def _fetch_sut_source_context(
        self,
        project: dict,
        gherkin_text: str,
        max_chars: int = 8000,
        include_fe_routes: bool = True,
    ) -> str:
        """R104.B — compose SUT source-code context for PW prompt injection.

        R105.D — accepts `include_fe_routes` flag. Newman gen calls with
        `False` to get backend-routes-only (FE routes irrelevant for API
        tests; saves prompt budget).

        Fetches via direct GitHub REST API (proven path; the npm
        `github-mcp-server` is a Git CLI tool, NOT the API MCP — verified
        by TODO comment in github_context.py:223). The agent-owned MCP
        scaffold (self._mcp_clients) is in place for when a proper
        GitHub-API MCP server (Go binary per upstream roadmap) lands;
        until then the concrete transport is REST. This is the right
        architecture: the agent OWNS the connection abstraction; the
        client implementation can be swapped without changing call sites.

        Fetches:
          - Frontend route files (Next.js pages/* + key selectors) via
            extract_frontend_routes() — httpx + GitHub REST
          - Backend route handlers (FastAPI/Express) via REST code search

        Returns formatted HARD CONSTRAINT block ready to append to the
        prompt. Returns "" if no signal — PW gen continues with existing
        R47.1b/R19c/R98.3 layers.
        """
        integrations = project.get("integrations") or {}
        if hasattr(integrations, "model_dump"):
            integrations = integrations.model_dump()
        token = (
            integrations.get("github_token")
            or __import__("os").environ.get("GITHUB_TOKEN", "")
        )
        if not token:
            # R330 P1c — FAIL LOUD, don't silently degrade. Source grounding is
            # unavailable → the generated tests for this SUT are NOT grounded in the
            # SUT's own code (they lean on DOM catalog + observed endpoints only).
            # Surface it (WARNING + a status the caller can stamp) so the operator
            # knows to configure GitHub or use R320 human correction — never a
            # silent fallback that obscures how grounded the tests really are.
            self._r330_source_grounding_status = "unavailable:no_github_token"
            log.warning(
                "R330: SOURCE GROUNDING UNAVAILABLE for project %s — no github_token/"
                "GITHUB_TOKEN. Tests are NOT source-grounded; see grounding-coverage. "
                "Configure a GitHub integration or use Refine-with-AI (R320) as the "
                "authoritative grounding source.",
                project.get("id") or project.get("name") or "?",
            )
            return ""
        self._r330_source_grounding_status = "available"
        try:
            from .github_context import extract_frontend_routes
        except Exception as _r330_exc:
            self._r330_source_grounding_status = "unavailable:github_context_import_error"
            log.warning("R330: source grounding unavailable — github_context import failed: %s", _r330_exc)
            return ""
        fe_routes: list[dict] = []
        be_routes: list[dict] = []
        if include_fe_routes:
            try:
                fe_routes = await extract_frontend_routes(project) or []
            except Exception as exc:
                log.debug("R104.B: extract_frontend_routes failed: %s", exc)
        try:
            be_routes = await self._r104_b_extract_backend_routes_rest(
                project=project,
                token=token,
                gherkin_text=gherkin_text,
            ) or []
            # R330 P3 — classify protocol per route. The per-protocol call-
            # convention map (_PROTO_CALL) branched on r["protocol"] since
            # birth, but routes only ever carried {method, path} — every
            # non-REST branch was dead code. Single choke-point: both
            # extraction paths (tree walk + /search/code) flow through here.
            # Killswitch ARTA_R330_PROTOCOL_DISABLE=1.
            if os.environ.get("ARTA_R330_PROTOCOL_DISABLE") != "1":
                from .protocol_discovery import classify_protocol as _r330_cp
                for _rt in be_routes:
                    if isinstance(_rt, dict) and not _rt.get("protocol"):
                        _rt["protocol"] = _r330_cp(_rt.get("path") or "")
        except Exception as exc:
            log.debug("R104.B: extract_backend_routes_rest failed: %s", exc)
        # R156.B.2 — classify per-endpoint token requirements by walking
        # R156.B.1's TOKEN_CHAINS. Each BE route with an auth_requirement
        # (set by R156.A.2) gains `required_tokens` (ordered chain) +
        # `token_chain` (full hop metadata). R156.B.4 prompt block uses
        # these to render explicit setup→action sequences.
        try:
            self._r156_b_2_classify_endpoint_tokens(be_routes)
        except Exception as exc:
            log.debug("R156.B.2: per-endpoint token classification failed: %s", exc)
        # R156.B.3 — resolve FK body fields to producer endpoints in the
        # same be_routes list. Stamps `data_dependencies` on routes whose
        # body_schema_source contains `<entity>_id` / `<entity>Id` fields
        # AND a producer GET endpoint exists.
        try:
            self._r156_b_3_resolve_data_dependencies(be_routes)
        except Exception as exc:
            log.debug("R156.B.3: FK data dependency resolution failed: %s", exc)
        # R156.C — backfill protocol field (defaults to "rest") + stamp
        # gen_handoff per route. R156.C.1 already classified inline at
        # extraction time for routes that hit the file-content fallback
        # path; this wrapper ensures every route has both fields.
        try:
            self._r156_c_classify_routes_inplace(be_routes)
        except Exception as exc:
            log.debug("R156.C: protocol/handoff stamping failed: %s", exc)
        # R156.A.3 — link each FE route's api_calls to the matching BE
        # route (with body_schema_source + auth_requirement attached) so
        # the LLM prompt sees not just "this component calls /api/X" but
        # the full request body + token-kind context per call site.
        try:
            self._r156_a_3_link_fe_to_be_routes(fe_routes, be_routes)
            # R211 B3.3 — stash the flattened Code→API links on the agent so the
            # PW gen path can surface them onto `risk` (no longer discarded).
            self._r211_code_api_links = self._r211_flatten_code_api_links(fe_routes)
        except Exception as exc:
            log.debug("R156.A.3: FE→BE call-graph linkage failed: %s", exc)
        if not fe_routes and not be_routes:
            return ""
        lines = ["[HARD CONSTRAINT — SUT SOURCE CODE TRUTH (via GitHub MCP)]"]
        if be_routes:
            lines.append("")
            lines.append("BACKEND ROUTES (from the SUT's actual handler files):")
            for r in be_routes[:25]:
                _m = (r.get("method") or "GET").upper()
                _p = r.get("path") or ""
                lines.append(f"  {_m:6s} {_p}")
                # R156.A.1 — surface request body schema source when extracted.
                # Capped per-route at 15 snippet lines to keep prompt budget
                # reasonable; full structured parsing deferred — the raw
                # class/interface snippet gives the LLM enough signal to
                # ground request body field names + types itself.
                _body_src = r.get("body_schema_source")
                if _body_src:
                    lines.append("    request_body_schema (from SUT source):")
                    _snippet_lines = _body_src.split("\n")[:15]
                    for _sl in _snippet_lines:
                        lines.append(f"      {_sl}")
                    if len(_body_src.split("\n")) > 15:
                        lines.append("      # (truncated — see SUT source for full schema)")
                # R156.A.2 — surface auth requirement when extracted.
                # aws_temp_creds, s3_presigned}. R156.B.4 prompt block uses
                # this to tell the LLM which token kind each endpoint expects.
                _auth = r.get("auth_requirement")
                if _auth:
                    _tk = _auth.get("token_kind") or "none"
                    _chain = _auth.get("decorator_chain") or []
                    _scopes = _auth.get("scopes") or []
                    _parts = [f"requires {{{_tk}}}"]
                    if _scopes:
                        _parts.append(f"scopes={_scopes}")
                    if _chain:
                        _parts.append(f"via=[{', '.join(_chain[:3])}]")
                    lines.append(f"    auth_requirement: " + "  ".join(_parts))
        if fe_routes:
            lines.append("")
            lines.append("FRONTEND ROUTES (from source — Next.js pages dir / React Router; component + api_calls hints):")
            for r in fe_routes[:25]:
                _p = r.get("route") or r.get("path") or ""
                _comp = r.get("component") or ""
                # R187.2a — compose the selector hint from the REAL keys
                # extract_frontend_routes populates (test_ids/buttons/form_fields).
                # Pre-R187 this read `selectors_hint` — a key NOTHING ever sets —
                # so the source-extracted selectors were silently dropped and the
                # LLM hallucinated selectors. Caps (8/6/8) bound prompt growth
                # (R119.A). Still honors a pre-set selectors_hint if present.
                _sel = r.get("selectors_hint") or ""
                if not _sel:
                    _sp = []
                    if r.get("test_ids"):
                        _sp.append("testids=" + ",".join(r["test_ids"][:8]))
                    if r.get("buttons"):
                        _sp.append("buttons=" + ",".join(str(b) for b in r["buttons"][:6]))
                    if r.get("form_fields"):
                        _sp.append("fields=" + ",".join(str(f) for f in r["form_fields"][:8]))
                    _sel = "; ".join(_sp)
                # R105.C — surface the route's api_calls so the LLM emits
                # accurate `waitForResponse` assertions matching the real
                # component → API wiring. Pre-R105.C the LLM hallucinated
                # endpoints in `waitForResponse(...)` despite getting the
                # route right; api_calls grounds it.
                _api_calls = r.get("api_calls") or []
                _parts = [f"  {_p:30s} ({_comp})"]
                if _sel:
                    _parts.append(f"selectors: {_sel}")
                if _api_calls:
                    _parts.append(f"api_calls: {', '.join(_api_calls[:5])}")
                lines.append("  ".join(_parts) if len(_parts) > 1 else _parts[0])
                # R156.A.3 — surface FE→BE call-graph links so the LLM
                # sees per FE route which BE handlers it invokes WITH
                # their body_schema + token_kind. Compact one-line-per-
                # link format; capped at 3 links per route to keep prompt
                # budget bounded (full set still on `api_call_links`).
                _links = r.get("api_call_links") or []
                if _links:
                    lines.append("    backend_links (FE → BE):")
                    for _lk in _links[:3]:
                        _lm = (_lk.get("method") or "GET").upper()
                        _lu = _lk.get("url") or ""
                        _ltk = (_lk.get("auth_requirement") or {}).get("token_kind") or ""
                        _has_schema = bool(_lk.get("body_schema_source"))
                        _suffix_parts = []
                        if _ltk:
                            _suffix_parts.append(f"token={_ltk}")
                        if _has_schema:
                            _suffix_parts.append("has_body_schema=yes")
                        _suffix = (" [" + ", ".join(_suffix_parts) + "]") if _suffix_parts else ""
                        lines.append(f"      {_lm:6s} {_lu}{_suffix}")
        # R156.B.4 — append the auth-graph + data-dependency HARD
        # CONSTRAINT block, rendering the accumulated outputs of
        # R156.A.1/A.2/A.3/B.1/B.2/B.3 + R156.I.2 in compact form.
        # Returns "" when no source-derived metadata was extracted, so
        # this is a no-op cost addition when MCP is unavailable.
        try:
            auth_graph_block = self._r156_b_4_render_auth_graph_block(be_routes)
            if auth_graph_block:
                lines.append(auth_graph_block)
        except Exception as exc:
            log.debug("R156.B.4: auth-graph block rendering failed: %s", exc)
        # R195 — topologically-ordered, protocol-tagged WORKFLOW PIPELINE
        # (datasource→dataset→app→agent-token→launch derived from the data-dep
        # DAG) so the spec establishes the full chain in order, not isolated deps.
        try:
            _r195_block = self._r195_workflow_pipeline_block(be_routes, gherkin_text)
            if _r195_block:
                lines.append("")
                lines.append(_r195_block)
        except Exception as exc:
            log.debug("R195: workflow-pipeline block rendering failed: %s", exc)
        lines.append("")
        lines.append(
            "USE THESE EXACT URLS in `page.goto(...)` and `page.request.X(url, ...)`.\n"
            "DO NOT invent paths absent from the lists above — the SUT will 404.\n"
            "When request_body_schema is shown for an endpoint, use ONLY those\n"
            "field names + types in your request body. Do NOT invent fields\n"
            "(R156.A.1 grounding — fields invented outside the schema will 400).\n"
            "[END SUT SOURCE CONTEXT]"
        )
        block = "\n".join(lines)
        return block[:max_chars]

    # ── Public API ────────────────────────────────────────────────────────────

    async def generate(
        self,
        gherkin_scenarios: list[str],
        risk_profiles: list[dict],
        requirement_id: str | None = None,
    ) -> dict[str, str]:
        """
        Generate automation scripts — ONE LLM call for ALL tools combined.

        Single prompt asks for Playwright + Newman + k6 scripts separated by markers.
        This minimizes LLM calls (1 instead of 3) to stay within rate limits.
        Returns: {filename: script_content} dict.
        """
        # Reset per-invocation error tracking so stale entries don't leak across reqs.
        self._last_tool_errors = {}
        # R127.B/C — reset per-script telemetry side-channel too
        self._last_script_metadata = {}

        if not gherkin_scenarios or not risk_profiles:
            return {}

        risk = risk_profiles[0] if risk_profiles else {}
        # F12-12: pass `risk` so the extractor can fall back to the requirement
        # id stored on the risk profile when ATDD produced gherkin without
        # the REQ-XXX-NNN marker (which previously minted orphan files like
        # R314 — the CANONICAL requirement_id (threaded from the caller) is
        # AUTHORITATIVE for filenames; every spec/collection/perf file is named
        # `sanitize_req_id(req_id)`. Pre-R314 `generate()` took no requirement_id, so
        # req_id was EXTRACTED from the Gherkin/risk — a lossy path that (a) missed
        # requirement TITLE → filenames drifted to a descriptive slug
        # (`kui_host_detail.spec.ts`) that breaks spec→requirement traceability and
        # stem-based scoping/regen across runs. Use the threaded id when present;
        # keep the extractor only as the legacy fallback.
        # R314 — stash the canonical id on the INSTANCE so it reaches EVERY per-tool
        # generator: generate_single/_generate_playwright/_generate_k6/_generate_newman
        # each independently call `_extract_req_id(gherkin, risk)` for their filename,
        # so a local var here would not reach them. `_extract_req_id` prefers this
        # when set. Reset per invocation (None when no id threaded) so it never leaks
        # across requirements.
        self._canonical_req_id = str(requirement_id).strip() if requirement_id else None
        req_id = (self._canonical_req_id
                  or self._extract_req_id(gherkin_scenarios[0] if gherkin_scenarios else "", risk))
        combined_gherkin = "\n\n".join(gherkin_scenarios)
        test_types = risk.get("test_types", ["UI"])

        # Map test types to tools
        tools_needed = []
        for tt in test_types:
            tool = self._select_tool(tt, risk)
            if tool not in [t for t, _ in tools_needed]:
                tools_needed.append((tool, tt))

        if not tools_needed:
            tools_needed = [("playwright", "UI")]

        # R213.K.16 — requirement→test-type validation. HTTP perf (k6) + API
        # (newman) tools REQUIRE the requirement to map to a real HTTP endpoint. An
        # gmail job to gmail_queue', 0 endpoints matching gmail/queue/job) has NO
        # HTTP endpoint → the LLM forces it onto unrelated real endpoints (storage
        # blobs) → noise. PRUNE k6+newman when the requirement has ZERO HTTP-
        # endpoint match; truthfully record it's not HTTP-perf/API-testable.
        # UI/security/a11y are app-level (kept). Killswitch
        # ARTA_R213_K16_HTTP_GATE_DISABLE=1.
        import os as _os_k16
        if (_os_k16.environ.get("ARTA_R213_K16_HTTP_GATE_DISABLE", "").lower() not in ("1", "true")
                and any(t in ("k6", "newman") for t, _ in tools_needed)):
            _k16_pid = (risk or {}).get("project_id") if isinstance(risk, dict) else None
            _k16_ok, _k16_matched = self._r213_k16_http_testable(combined_gherkin, _k16_pid)
            if not _k16_ok:
                _k16_pruned = [t for t, _ in tools_needed if t in ("k6", "newman")]
                tools_needed = [(t, tt) for t, tt in tools_needed if t not in ("k6", "newman")]
                for _pt in _k16_pruned:
                    self._last_tool_errors[_pt] = (
                        "R213.K.16: requirement maps to NO HTTP endpoint "
                        "(async/event-driven op) — not HTTP-perf/API-testable"
                    )
                log.warning(
                    "R213.K.16: %s pruned %s — requirement maps to NO HTTP endpoint "
                    "(0 distinctive-term match vs the SUT API surface); async/event-"
                    "driven op is not HTTP-testable. Remaining tools: %s",
                    req_id, _k16_pruned, [t for t, _ in tools_needed],
                )

        # R300 — Newman-only prune: a req whose relevant endpoints are ALL
        # streaming/event (response-stream/SSE) is not Newman-testable (Newman
        # buffers a single response, can't assert a streamed body → sc=0 +
        # `expected undefined` cascade). Route to the pytest analytics runtime.
        if any(t == "newman" for t, _ in tools_needed):
            _r300_pid = (risk or {}).get("project_id") if isinstance(risk, dict) else None
            if self._r300_req_is_streaming_only(combined_gherkin, _r300_pid):
                tools_needed = [(t, tt) for t, tt in tools_needed if t != "newman"]
                self._last_tool_errors["newman"] = (
                    "R300: requirement endpoints are streaming/event (response-"
                    "stream/SSE) — Newman can't assert a streamed body; covered by "
                    "the pytest analytics runtime")
                log.warning(
                    "R300: %s pruned newman — streaming-only endpoint set "
                    "(not request→single-response testable)", req_id)

        # R212 KEYSTONE (covers ALL strategies incl. the batch path that bypasses
        # _generate_playwright) — for an API-contract req with a derivable cm
        # chain, build the deterministic chain spec and REMOVE playwright from
        # tools_needed so neither the batch nor single/sequential LLM gen wastes
        # time on a PW spec that target#1 would discard. The chain is merged back
        # into the result via _r212_with_chain at each return.
        self._r212_pending_chain = None
        if any(t == "playwright" for t, _ in tools_needed):
            _r212_cs = self._r212_build_deterministic_chain(risk, combined_gherkin, req_id)
            if _r212_cs is not None:
                self._r212_pending_chain = {_r212_cs.filename: _r212_cs.content}
                self._last_script_metadata["playwright"] = dict(_r212_cs.metadata or {})
                # R213 Fix 1 — the deterministic chain is ADDITIVE by default:
                # KEEP playwright in tools_needed so the UI spec is ALSO generated
                # (broad UI coverage) alongside the grounded API-contract chain.
                # Pre-R213, R212 REMOVED playwright → api-contract reqs lost ALL UI
                # coverage (bulk-regen f57cd7dd collapsed PW 363→~few specs, all
                # chains; attributable rate looked high only because the
                # denominator collapsed). The chain (`{req}_chain.spec.ts`) and the
                # UI spec (`{req}.spec.ts`) are SEPARATE files → they coexist. The
                # chain gives grounded API-contract coverage; the UI spec gives UI
                # behavior coverage (its failures now attribute truthfully via
                # V4.1 + TDZ). Killswitch ARTA_R213_CHAIN_ADDITIVE_DISABLE=1 →
                # revert to R212 replace-behavior (chain only, no UI spec).
                import os as _os_add
                if _os_add.environ.get("ARTA_R213_CHAIN_ADDITIVE_DISABLE", "").lower() in ("1", "true"):
                    tools_needed = [(t, tt) for t, tt in tools_needed if t != "playwright"]
                    log.info("R212 KEYSTONE: %s → deterministic chain PW; removed playwright "
                             "from LLM gen (%d tool(s) remain for LLM)", req_id, len(tools_needed))
                    if not tools_needed:
                        return dict(self._r212_pending_chain)
                else:
                    log.info("R213 Fix1: %s → deterministic chain PW (ADDITIVE) + KEEP "
                             "playwright UI gen for coverage (chain + UI spec coexist)", req_id)

        # R213.K.20 — DEFER axe out of the batch/multi-tool LLM call. The
        # claude_code BATCH strategy unreliably emits the `--- SCRIPT: axe ---`
        # section (OMITS it → R125.M "Missing ['axe']", or TRUNCATES the combined
        # is small and has a dedicated GROUNDED generator (`_generate_accessibility`
        # — real-route grounding + the R213.K.17 shared-helper template + dedup).
        # Generate it SEPARATELY and merge via `_r212_with_chain` (mirrors the R212
        # chain pattern), removing it from the LLM tool set. Killswitch
        # ARTA_R213_K20_AXE_DEFER_DISABLE=1.
        self._r213_k20_pending_axe = None
        _k20_axe_tt = next((tt for t, tt in tools_needed if t == "axe"), None)
        import os as _os_k20
        if (_k20_axe_tt is not None
                and _os_k20.environ.get("ARTA_R213_K20_AXE_DEFER_DISABLE", "").lower() not in ("1", "true")):
            tools_needed = [(t, tt) for t, tt in tools_needed if t != "axe"]
            try:
                _k20_axe = await self._generate_accessibility(combined_gherkin, risk)
                self._r213_k20_pending_axe = {_k20_axe.filename: _k20_axe.content}
                if getattr(_k20_axe, "metadata", None):
                    self._last_script_metadata["axe"] = dict(_k20_axe.metadata)
                log.info("R213.K.20: generated axe via _generate_accessibility (deferred from "
                         "batch; %d LLM tool(s) remain) for %s", len(tools_needed), req_id)
            except Exception as _k20_exc:
                log.warning("R213.K.20: deferred axe gen failed for %s: %s", req_id, _k20_exc)
                self._last_tool_errors["axe"] = f"{type(_k20_exc).__name__}: {str(_k20_exc)[:120]}"
            if not tools_needed:
                # axe was the only LLM tool → return it (+ any pending PW chain)
                return self._r212_with_chain(dict(self._r213_k20_pending_axe or {}))

        # If only one tool, use the single-tool generator
        if len(tools_needed) == 1:
            tool, _ = tools_needed[0]
            try:
                script = await self.generate_single(combined_gherkin, tool, risk)
                # R127.B/C — stash per-script metadata (decomposition flags,
                # escalation outcomes) on the side-channel so tests.py can
                # merge into the persisted test row's `_gen_metrics`.
                if getattr(script, "metadata", None):
                    self._last_script_metadata[tool] = dict(script.metadata)
                return self._r212_with_chain({script.filename: script.content})
            except Exception as e:
                log.warning("Script generation failed for %s/%s: %s", req_id, tool, e)
                self._last_tool_errors[tool] = f"{type(e).__name__}: {str(e)[:120]}"
                return self._r212_with_chain({})

        # ── Smart Orchestration Strategy ──────────────────────────────────
        provider = getattr(self._client, "provider", LLMProvider.ANTHROPIC)

        # Strategy A: Sequential (Local / Smaller Models) — High Stability
        if provider == LLMProvider.OLLAMA:
            return self._r212_with_chain(
                await self.generate_sequential(combined_gherkin, tools_needed, risk))

        # Strategy B: Batch (Cloud APIs) — Cost & Token Optimized
        #
        # R253.PW KEYSTONE — the batch prompt generates ALL tools in ONE LLM
        # call and BYPASSES the per-tool generators (_generate_playwright etc.)
        # where the R98.3 status-grounding + R42.1 selector-grounding validators
        # getByText + status-404-on-success specs that the single-tool path
        # would have grounded/blocked). Playwright is the tool most sensitive to
        # grounding (selectors + API status), so pull it OUT of the batch and
        # generate it via generate_single (which routes through
        # _generate_playwright → full grounding). The remaining API/perf/sec/a11y
        # tools stay in the cost-optimized batch. Killswitch
        # ARTA_R253_PW_UNBATCH_DISABLE=1 restores the all-in-batch behavior.
        _r253_pw_scripts: dict = {}
        if (os.environ.get("ARTA_R253_PW_UNBATCH_DISABLE") != "1"
                and any(t == "playwright" for t, _ in tools_needed)):
            try:
                _pw_script = await self.generate_single(combined_gherkin, "playwright", risk)
                if _pw_script and getattr(_pw_script, "filename", None):
                    _r253_pw_scripts[_pw_script.filename] = _pw_script.content
                    if getattr(_pw_script, "metadata", None):
                        self._last_script_metadata["playwright"] = dict(_pw_script.metadata)
                log.info("R253.PW: generated Playwright via single-tool grounding path "
                         "(out-of-batch) for %s", req_id)
            except Exception as _r253_exc:
                log.warning("R253.PW: out-of-batch Playwright gen failed for %s: %s "
                            "— falling back to in-batch PW", req_id, _r253_exc)
                _r253_pw_scripts = {}
            if _r253_pw_scripts:
                tools_needed = [(t, tt) for t, tt in tools_needed if t != "playwright"]
                if not tools_needed:
                    # PW was the only tool → return the grounded PW result.
                    return self._r212_with_chain(_r253_pw_scripts)

        log.info("Cloud API detected (%s): Using Batch Strategy for %s: %s",
                 provider, req_id, [t for t, _ in tools_needed])

        tool_instructions = []
        for tool, tt in tools_needed:
            lang = TOOL_LANGUAGE.get(tool, "typescript")
            tool_instructions.append(f"=== {tool.upper()} ({tt}) ===\nLanguage: {lang}")

        tools_block = "\n".join(tool_instructions)
        gherkin_sanitized = self._sanitize_for_prompt(combined_gherkin)

        # G4.2 (I10): Prepend advisory block with recurring failure signatures for this project.
        # Helps the LLM avoid patterns that have repeatedly failed in past runs.
        advisory = ""
        project_id = risk.get("project_id") if isinstance(risk, dict) else None
        if project_id:
            try:
                from .feedback_corpus import feedback_corpus
                advisory = feedback_corpus.format_advisory_block(project_id=project_id, limit=5)
                if advisory:
                    advisory = advisory + "\n"
            except Exception:
                advisory = ""

        prompt = (
            "Generate automation test scripts for ALL of the following tools from these Gherkin scenarios.\n\n"
            f"{advisory}"
            f"GHERKIN:\n{gherkin_sanitized}\n\n"
            "Generate scripts for EACH tool below. Separate each script with the exact marker line shown.\n"
            "Output ONLY code for each section — no prose, no explanations.\n\n"
            f"{tools_block}\n\n"
            "[REQUIRED FORMAT — deviation will cause test generation failure]\n"
            "Use EXACTLY this separator format (three dashes, space, 'SCRIPT:', space, tool, space, three dashes):\n"
            "--- SCRIPT: <tool_name> ---\n"
            "Do NOT use === or *** or any other separator. Do NOT add a 'Here are the scripts:' preamble.\n"
            "Start your response directly with the first marker.\n\n"
            "For each tool, output:\n"
            "--- SCRIPT: <tool_name> ---\n"
            "<complete script code>\n\n"
            "Example format:\n"
            "--- SCRIPT: playwright ---\n"
            "import { test, expect } from '@playwright/test';\n\n"
            "--- SCRIPT: newman ---\n"
            "// ... valid JSON Postman collection\n"
        )

        # R274 — F1 AC-traceability, in the BATCH prompt.
        #
        # `_validate_response` REJECTS any PW spec with >=2 tests and zero
        # `// AC:` comments, and the canonical PLAYWRIGHT_GENERATION template
        # asks for them in 3 places -- but the batch strategy builds its OWN
        # prompt (tool_instructions here are just "=== PLAYWRIGHT (ui) ===
        # Language: typescript"), so on this path the LLM is NEVER TOLD. It
        # cannot comply with a rule it never saw, so every attempt is rejected
        # rejected on "zero `// AC:` comments" AFTER the catalog fix had already
        # cleared unknown_endpoint and semantic_intent_mismatch -- i.e. this
        # prompt gap was the only thing left blocking the regen.
        #
        # Third instance of the same class (R219.K: batch bypassed post-LLM
        # processing; R273: escalation bypassed the validator): a parallel gen
        # path drifting from the canonical one. Killswitch:
        # ARTA_R274_BATCH_AC_PROMPT_DISABLE=1.
        if any(t == "playwright" for t, _ in tools_needed):
            import os as _os_r274
            if _os_r274.environ.get("ARTA_R274_BATCH_AC_PROMPT_DISABLE") != "1":
                prompt += (
                    "\n[PLAYWRIGHT — F1 TRACEABILITY (REQUIRED; the spec is REJECTED without it)]\n"
                    "Every test() MUST carry an acceptance-criterion comment on the line ABOVE it:\n"
                    "  // AC: <ac_id>            <- copied VERBATIM from the Gherkin, e.g. AC-OR-022-01\n"
                    "  test('<ac_id>: <gherkin scenario title>', async ({ page }) => { ... });\n"
                    "Use the AC id from the Gherkin scenario the test covers (its `AC-...` id token, e.g.\n"
                    "its title/tag). If a scenario carries no explicit id, use its exact scenario\n"
                    "title after `// AC: `. NEVER invent an id that is not in the Gherkin above —\n"
                    "the comment is a traceability link a regression bisect follows back to the\n"
                    "originating criterion, so a wrong id is worse than a missing test.\n"
                )

        api_endpoints = risk.get("_api_endpoints", "")
        # P1 (relevance-filter) — the injected `_api_endpoints` is the FULL captured
        # surface (tests.py formats ALL endpoints). Source-grounding grew it to
        # PW assertion over-spec 68→180, timeouts 6→59, 4 reqs' combined-5-tool
        # call blew the 600s window → 0 tests, NET-regressing pass rate 52.9→38.6%
        # even though it fixed 405s. Cap to THIS req's top-N Gherkin-relevant
        # endpoints (the sequential PW path already does this at the _filter call
        # site). Killswitch ARTA_P1_ENDPOINT_RELEVANCE_DISABLE=1.
        if api_endpoints:
            import os as _os_p1
            if _os_p1.environ.get("ARTA_P1_ENDPOINT_RELEVANCE_DISABLE") != "1":
                try:
                    _filtered = self._filter_endpoints_by_gherkin(
                        api_endpoints, combined_gherkin, top_n=15)
                    if _filtered.strip():
                        api_endpoints = _filtered
                except Exception as _p1_exc:
                    log.debug("P1 endpoint relevance-filter skipped (batch) for %s: %s",
                              req_id, _p1_exc)
            prompt += f"\n\n{api_endpoints}\n"
            # R330 P2 — inject the KNOWN param value-domains + constraints (OpenAPI
            # enum/min/max/pattern + observed field values) so the batch path (the
            # claude_code real-SUT route, R219.K) generates real param values
            # upstream instead of guessing. Same Gherkin-relevance filter + cap as
            # R251; empty when nothing is known (never fabricates). Killswitch
            # ARTA_R330_PARAM_CONSTRAINTS_DISABLE=1.
            try:
                _r330_pid = risk.get("project_id") or ""
                if _r330_pid:
                    from .api_discovery import (
                        _load_captured_endpoints as _r330_load,
                        param_constraint_block as _r330_pcb,
                        enrich_endpoints_with_openapi_params as _r330_enrich,
                        select_param_relevant_endpoints as _r330_select,
                    )
                    _r330_caps = _r330_load(_r330_pid) or []
                    # P2b — enrich FIRST (fills + persists params_detail), then
                    # relevance-filter with the truthful fallback + counters
                    # (constraint-carrying endpoints only when Gherkin matches none).
                    _r330_all = _r330_enrich(_r330_pid, list(_r330_caps))
                    _r330_rel, _r330_stats = _r330_select(_r330_all, combined_gherkin)
                    _r330_blk = _r330_pcb(_r330_rel)
                    if _r330_blk:
                        prompt += "\n\n" + _r330_blk + "\n"
                    log.info(
                        "R330 P2b: param block %s (batch) for %s (known=%d relevant=%d fallback=%s)",
                        "injected" if _r330_blk else "EMPTY", req_id,
                        _r330_stats.get("known", 0), _r330_stats.get("relevant", 0),
                        _r330_stats.get("fallback", "-"))
            except Exception as _r330_bexc:
                log.debug("R330 P2: param-constraint inject (batch) skipped for %s: %s",
                          req_id, _r330_bexc)
            # R330 P2b (G1) — batch path also gets request BODIES (R295/R297) and
            # REAL entity ids (R251), PW-parity. Killswitch shared with the
            # Newman wire (ARTA_R330_P2B_NEWMAN_DISABLE).
            if os.environ.get("ARTA_R330_P2B_NEWMAN_DISABLE") != "1":
                try:
                    _bk_pid_p2b = risk.get("project_id") or "" if isinstance(risk, dict) else ""
                    if _bk_pid_p2b:
                        _bk_b295 = self._r295_request_body_block(_bk_pid_p2b, combined_gherkin)
                        if _bk_b295:
                            prompt += "\n" + _bk_b295 + "\n"
                        _bk_b251 = self._r251_real_data_block(_bk_pid_p2b, combined_gherkin)
                        if _bk_b251:
                            prompt += "\n" + _bk_b251 + "\n"
                except Exception as _bk_p2b_exc:
                    log.debug("R330 P2b: batch body/real-id blocks skipped for %s: %s",
                              req_id, _bk_p2b_exc)

        # G3/R219 — the batch prompt does NOT import PLAYWRIGHT_GENERATION, so
        # its PW section lacks the key gen constraints. Append them here scoped
        # to the playwright script (assertion specificity, no self-auth, no
        # localStorage-before-nav). Backstops the deterministic rewriters.
        if any(t == "playwright" for t, _ in tools_needed):
            prompt += (
                "\n\n[PLAYWRIGHT SCRIPT — HARD CONSTRAINTS]\n"
                "- Auth is PRESET by storageState. DO NOT write a login helper or "
                "POST to /auth/login /login /signin, and DO NOT inject auth cookies "
                "(context.addCookies) — just page.goto an authenticated route.\n"
                "- NEVER call localStorage (clear/getItem/setItem) BEFORE the first "
                "page.goto — it throws SecurityError on about:blank. Navigate first.\n"
                "- Inside page.evaluate, use only browser globals; Node vars "
                "(API_BASE/BASE_URL) are undefined there — pass them as args.\n"
                "- ASSERTION SPECIFICITY: assert observable PRESENCE (resp.ok()/status "
                "class, a field EXISTS, an element is visible), NOT an exact value you "
                "did not capture, and NOT response-envelope shape unless the body was "
                "captured. Negative tests assert the status CLASS ([400,401,403]). "
                "SECURITY tests (SQL-injection/XSS/payload): the SUT may SANITIZE and "
                "return 200 — assert the UNION [200,400,401,403,404,422], never a "
                "4xx-only array (never include 5xx).\n"
                "- NEVER INVENT RESPONSE DATA (run-c3d56e: 68 fails). Do NOT assert "
                "invented envelope KEYS (body.code/body.status/body.data.subscriptions "
                "— you did not capture these), enum VALUES (toBe('SUCCESS')), exact "
                "COUNTS (toBe(4)/toHaveLength(3)), seed IDs (toContain('ASSET-LAP01')), "
                "URLs, timestamps or prose messages. Assert TYPE/STRUCTURE + status-code "
                "SETS instead: expect([200,401,404]).toContain(response.status()); "
                "expect(typeof body.x).toBe('string'); expect(Array.isArray(body.x)).toBe(true). "
                "Only assert an exact value that ECHOES a request input or a fixture you "
                "were given.\n"
                "- GUARD before .length/.map/.find: use optional chaining + a fallback "
                "(`(body?.items ?? []).length`) so a missing key fails the assertion "
                "truthfully instead of throwing a TypeError.\n"
                "- Selectors: role+name from the DOM catalog (getByRole/getByText); "
                "this SUT has NO data-testid. Never invent selectors.\n"
            )
            # R248 (batch) — login/SSO reqs: steer to API-first auth testing (the
            # login page / external IdP is ungroundable → UI login TIMES OUT).
            if os.environ.get("ARTA_R248_LOGIN_API_FIRST_DISABLE") != "1":
                prompt += self._r248_login_flow_pw_constraint(combined_gherkin)

        # G3.N (batch) — the batch prompt has no Newman assertion template, so
        # its Newman section over-specifies status codes + body shapes and
        # guesses HTTP methods → the run-c3d56e residual (~235 Newman fails: 405
        # wrong-method, "expected [400,404] to include 200", negative asserts
        # pinned to [401,403,404] missing 400/405). Append the status-CLASS +
        # method-grounding constraint scoped to the newman section. Killswitch
        # ARTA_G3N_NEWMAN_ASSERT_DISABLE=1.
        import os as _os_g3n
